    // ── post-launch session capture (GH #243) ──
    //
    // The capture harvests a lazily-created agent session ID (opencode) so
    // the next spawn resumes it instead of starting over. Every failure mode
    // here is silent by construction (empty stdout looks like "no session
    // yet"), so the environment it runs in has to be the PTY's, not the
    // .app's launchd env.

    #[test]
    fn a_docker_capture_reads_the_mounted_state_not_the_users_own() {
        // Reported: a Docker main-checkout muse task resumed into "retained
        // session not found: session <uuid> has no saved log". The capture
        // command runs on the HOST, so it was reading ~/.local/share/muse and
        // handing the container a session id only the host had ever seen.
        let cwd = std::env::temp_dir().to_string_lossy().into_owned();
        let cmd = "printf %s \"${XDG_DATA_HOME:-unset}\"";

        // Not a Docker task: the user's own XDG rules stay untouched, because
        // the agent really did write there.
        let host = run_capture_command_blocking(cmd, &cwd, Some("muse"), false).unwrap();
        assert!(!host.contains("docker-agents"), "host capture was redirected: {host}");

        // A Docker task: pointed at the dir the container wrote through, and
        // `$XDG_DATA_HOME/muse` has to land exactly on the mount's host side.
        let dock = run_capture_command_blocking(cmd, &cwd, Some("muse"), true).unwrap();
        //
        // Asserted on SHAPE, not by comparing against a freshly-computed
        // `agent_config_host_dir`: that reads `TERMIC_DATA_DIR`, which is
        // process-wide, and other tests in this binary set and clear it in
        // parallel threads, so the two reads could disagree mid-test. The
        // shape is the contract anyway - `$XDG_DATA_HOME/muse` must land on
        // `docker-agents/muse/local/share/muse`, which is exactly what
        // `host_subpath_for("/root/.local/share/muse")` produces (pinned in
        // docker.rs's own test).
        assert!(dock.replace('\\', "/").ends_with("docker-agents/muse/local/share"), "got {dock}");

        // An agent with no `.local/share` state dir is left alone rather than
        // pointed at a directory that does not exist.
        assert!(run_capture_command_blocking(cmd, &cwd, Some("claude"), true)
            .unwrap().contains("unset")
            || !run_capture_command_blocking(cmd, &cwd, Some("claude"), true)
                .unwrap().contains("docker-agents"));
    }

    #[test]
    fn capture_runs_in_cwd_and_trims_stdout() {
        let dir = tempdir().unwrap();
        fs::write(dir.path().join("marker"), "ses_abc123\n").unwrap();
        let cwd = dir.path().to_string_lossy().into_owned();
        // Pipelines are the whole point of the shell here (the shipped
        // opencode capture is `… | grep … | cut …`).
        let out = run_capture_command_blocking("cat marker | cut -d' ' -f1", &cwd, None, false).unwrap();
        assert_eq!(out, "ses_abc123");
    }

    #[cfg(unix)] // unix paths / tools; the Windows behaviour differs by design
    #[test]
    fn capture_sees_the_login_shell_path() {
        // The regression: a CLI installed outside the launchd PATH (opencode
        // lands in ~/.opencode/bin, Homebrew in /opt/homebrew/bin) has to be
        // findable, or the capture returns "" and the ID is never stored.
        let dir = tempdir().unwrap();
        let cwd = dir.path().to_string_lossy().into_owned();
        let seen = run_capture_command_blocking("printf %s \"$PATH\"", &cwd, None, false).unwrap();
        assert_eq!(seen, shell_env::spawn_env().0);
    }

    #[test]
    fn capture_reports_stdout_only() {
        // A "command not found" (the GH #243 failure) writes to stderr and
        // must not be mistaken for a session ID.
        let dir = tempdir().unwrap();
        let cwd = dir.path().to_string_lossy().into_owned();
        let out = run_capture_command_blocking(
            "echo noise >&2; definitely-not-a-real-binary-243", &cwd, None, false).unwrap();
        assert_eq!(out, "");
    }

    // ── create-time resume-args override ──
    //
    // The New Task dialog sets the same field the task menu's "Resume
    // override" edits, so the two paths have to agree on what a blank box
    // means: no override, NOT an override that resumes with nothing.

    #[test]
    fn blank_resume_override_means_no_override() {
        assert_eq!(normalized_resume_override(None), None);
        assert_eq!(normalized_resume_override(Some(String::new())), None);
        assert_eq!(normalized_resume_override(Some("   \n\t ".into())), None);
    }

    #[test]
    fn resume_override_is_stored_trimmed_and_verbatim() {
        // Verbatim to the token: placeholders expand at spawn, and quoting
        // is the caller's business, so nothing here may rewrite the string.
        assert_eq!(
            normalized_resume_override(Some("  --resume {WORKSPACE_NAME}  ".into())),
            Some("--resume {WORKSPACE_NAME}".to_string()),
        );
        assert_eq!(
            normalized_resume_override(Some("resume --last".into())),
            Some("resume --last".to_string()),
        );
    }

    // ── the editor's binary-file contract ──
    //
    // `task_file_read`'s UTF-8 rejection is not just an error string: the
    // frontend matches it (`/valid UTF-8/i` in src/lib/editorError.ts) to
    // decide whether the editor pane shows a calm "binary file, open it
    // elsewhere" notice with Open/Reveal buttons, or a red raw error. A
    // reword here would silently drop that pane back to red text with no
    // way out, and nothing else would fail. Hence this test.

    #[test]
    fn binary_read_is_rejected_with_the_message_the_editor_matches() {
        // A lone 0xFF is never valid UTF-8 — the .xlsx/.zip/compiled-blob case.
        let err = decode_task_file(vec![0xFF, 0xFE, 0x00, 0x01]).unwrap_err();
        assert!(
            err.to_lowercase().contains("valid utf-8"),
            "editorError.ts matches /valid UTF-8/i against this message; got {err:?}",
        );
    }

    #[test]
    fn text_still_decodes_verbatim() {
        // The other half of the contract: real text must not take the
        // binary branch, including non-ASCII that is perfectly valid UTF-8.
        assert_eq!(decode_task_file("héllo\n".as_bytes().to_vec()).unwrap(), "héllo\n");
        assert_eq!(decode_task_file(Vec::new()).unwrap(), "");
    }

    #[test]
    fn a_big_binary_reports_binary_rather_than_too_large() {
        // The ordering this feature turns on. Both things are true of this
        // file; only one of them leads anywhere useful, so binary must win.
        let dir = tempdir().unwrap();
        let p = dir.path().join("big.bin");
        let mut bytes = vec![0xFFu8; 64];
        bytes.extend(std::iter::repeat(b'a').take(4096));
        fs::write(&p, bytes).unwrap();
        let err = read_text_file_capped(&p, 1024).unwrap_err();
        assert!(
            err.to_lowercase().contains("valid utf-8"),
            "a big binary must read as binary, not as too-large; got {err:?}",
        );
    }

    #[test]
    fn a_big_text_file_is_rejected_with_the_message_the_editor_matches() {
        let dir = tempdir().unwrap();
        let p = dir.path().join("big.txt");
        fs::write(&p, vec![b'a'; 4096]).unwrap();
        let err = read_text_file_capped(&p, 1024).unwrap_err();
        assert!(
            err.contains("too large to preview"),
            "editorError.ts matches /too large to preview/i against this message; got {err:?}",
        );
        // The size is parsed out of it to name the file's size in the notice.
        assert!(err.contains("4096 bytes"), "the byte count must survive; got {err:?}");
    }

    #[test]
    fn text_longer_than_the_sniff_window_still_reads_whole() {
        // The sniff reads a prefix and the rest is read from the SAME handle,
        // so an off-by-one there would silently truncate every file over 8 KB.
        let dir = tempdir().unwrap();
        let p = dir.path().join("long.txt");
        // Multi-byte, so a boundary landing mid-character is exercised too.
        let body = "héllo wörld\n".repeat(2000);
        fs::write(&p, &body).unwrap();
        assert!(body.len() > TEXT_SNIFF_BYTES as usize);
        assert_eq!(read_text_file_capped(&p, 2_000_000).unwrap(), body);
    }

    #[test]
    fn the_read_budget_saturates_when_the_sniff_already_overran_the_cap() {
        // Reachable only by a file that GREW between the fstat and the sniff,
        // which is why the arithmetic is tested here rather than raced in a
        // temp dir: a plain `cap + 1 - already` panics in a debug build, and
        // tauri:dev IS a debug build.
        assert_eq!(remaining_read_budget(1024, 8192), 0);
        assert_eq!(remaining_read_budget(1024, 1025), 0);
        // The ordinary case still gets the one byte that makes an over-cap
        // file observable rather than silently truncated.
        assert_eq!(remaining_read_budget(2_000_000, 8192), 2_000_000 + 1 - 8192);
        assert_eq!(remaining_read_budget(1024, 0), 1025);
    }

    #[test]
    fn head_is_binary_ignores_a_character_cut_by_the_window() {
        // "é" is two bytes; a window ending between them is TEXT, not binary.
        let bytes = "aé".as_bytes();
        assert!(!head_is_binary(&bytes[..bytes.len() - 1]));
        assert!(head_is_binary(&[b'a', 0xFF, b'b']));
    }

    #[test]
    fn read_text_file_capped_rejects_a_directory() {
        let dir = tempdir().unwrap();
        assert!(read_text_file_capped(dir.path(), 1024).is_err());
    }

    // ── find-in-files backends (GH #181) ──
    //
    // Both parsers feed the same GrepHit contract, so the frontend never
    // learns which backend ran. These pin the shape of that contract.

    #[test]
    fn git_grep_line_parses_into_a_hit_without_ranges() {
        let h = parse_git_grep_line("src/lib.rs:42:7:  let x = 1;").expect("a match line");
        assert_eq!(h.path, "src/lib.rs");
        assert_eq!((h.line, h.col), (42, 7));
        assert_eq!(h.preview, "  let x = 1;");
        assert!(h.ranges.is_empty(), "git grep can't report match ranges, the frontend re-matches");
    }

    #[test]
    fn git_grep_line_keeps_colons_that_belong_to_the_code() {
        // splitn(4) matters: `a::b` in the preview must not be eaten.
        let h = parse_git_grep_line("s.rs:1:1:foo::bar(x:y)").expect("a match line");
        assert_eq!(h.preview, "foo::bar(x:y)");
    }

    #[test]
    fn git_grep_rejects_non_match_output() {
        assert!(parse_git_grep_line("").is_none());
        assert!(parse_git_grep_line("Binary file x matches").is_none());
        assert!(parse_git_grep_line("src/lib.rs:0:1:zero line number").is_none());
    }

    #[test]
    fn rg_match_event_carries_every_range_on_the_line() {
        let ev = r#"{"type":"match","data":{"path":{"text":"src/a.ts"},"lines":{"text":"foo bar foo\n"},"line_number":9,"absolute_offset":0,"submatches":[{"match":{"text":"foo"},"start":0,"end":3},{"match":{"text":"foo"},"start":8,"end":11}]}}"#;
        let h = parse_rg_json_line(ev).expect("a match event");
        assert_eq!(h.path, "src/a.ts");
        assert_eq!(h.line, 9);
        assert_eq!(h.preview, "foo bar foo", "trailing newline must be stripped");
        assert_eq!(h.ranges, vec![[0, 3], [8, 11]]);
        assert_eq!(h.col, 1, "col is 1-based, same contract as git grep --column");
    }

    #[test]
    fn rg_ranges_are_utf16_not_byte_offsets() {
        // rg counts bytes. "héllo " is 7 bytes but 6 UTF-16 units, so a
        // byte-offset range would paint one char to the right of the match.
        let ev = r#"{"type":"match","data":{"path":{"text":"a.txt"},"lines":{"text":"héllo world\n"},"line_number":1,"submatches":[{"match":{"text":"world"},"start":7,"end":12}]}}"#;
        let h = parse_rg_json_line(ev).expect("a match event");
        assert_eq!(h.ranges, vec![[6, 11]]);
        assert_eq!(&h.preview[..], "héllo world");
        // Sanity: the UTF-16 range actually spans the matched word.
        let utf16: Vec<u16> = h.preview.encode_utf16().collect();
        let picked = String::from_utf16(&utf16[6..11]).unwrap();
        assert_eq!(picked, "world");
    }

    #[test]
    fn rg_skips_events_that_are_not_matches() {
        assert!(parse_rg_json_line(r#"{"type":"begin","data":{"path":{"text":"a.ts"}}}"#).is_none());
        assert!(parse_rg_json_line(r#"{"type":"end","data":{"path":{"text":"a.ts"}}}"#).is_none());
        assert!(parse_rg_json_line("not json at all").is_none());
    }

    #[test]
    fn rg_drops_matches_it_cannot_decode() {
        // Non-UTF-8 path: rg sends {"bytes": base64} instead of {"text"}.
        // Guessing an encoding would put a garbage row in the results.
        let ev = r#"{"type":"match","data":{"path":{"bytes":"YS50eHQ="},"lines":{"text":"hit\n"},"line_number":1,"submatches":[{"match":{"text":"hit"},"start":0,"end":3}]}}"#;
        assert!(parse_rg_json_line(ev).is_none());
    }

    #[cfg(unix)]
    #[test]
    fn path_probe_only_accepts_an_executable_file() {
        use std::os::unix::fs::PermissionsExt;
        let dir = tempdir().unwrap();
        let empty = dir.path().join("empty");
        let real = dir.path().join("real");
        fs::create_dir_all(&empty).unwrap();
        fs::create_dir_all(&real).unwrap();

        // A non-executable file with the right name must not win.
        fs::write(real.join("rg"), b"#!/bin/sh\n").unwrap();
        let path = format!("{}:{}", empty.display(), real.display());
        assert!(find_on_path("rg", &path).is_none(), "a chmod-less file is not a backend");

        fs::set_permissions(real.join("rg"), fs::Permissions::from_mode(0o755)).unwrap();
        assert_eq!(find_on_path("rg", &path), Some(real.join("rg")));
        assert!(find_on_path("rg", "").is_none(), "an empty PATH must not panic");
    }

    // The backend is memoized for the whole session, and the login-shell
    // PATH lands asynchronously. Caching a miss read off the static
    // fallback (no /opt/homebrew/bin) would pin git grep until relaunch
    // for someone who has rg installed, so only these three combinations
    // may be kept.
    #[test]
    fn a_miss_on_the_fallback_path_is_never_memoized() {
        assert!(!backend_verdict_is_final(false, false), "ask again once the real PATH lands");
        assert!(backend_verdict_is_final(false, true), "a miss on the final PATH is the answer");
    }

    #[test]
    fn finding_rg_is_final_whatever_path_it_came_from() {
        // The binary exists at that path; a later PATH can't unfind it.
        assert!(backend_verdict_is_final(true, false));
        assert!(backend_verdict_is_final(true, true));
    }

    #[cfg(unix)]
    #[test]
    fn path_probe_takes_the_first_hit_in_path_order() {
        use std::os::unix::fs::PermissionsExt;
        let dir = tempdir().unwrap();
        let (first, second) = (dir.path().join("first"), dir.path().join("second"));
        fs::create_dir_all(&first).unwrap();
        fs::create_dir_all(&second).unwrap();
        for d in [&first, &second] {
            fs::write(d.join("rg"), b"x").unwrap();
            fs::set_permissions(d.join("rg"), fs::Permissions::from_mode(0o755)).unwrap();
        }
        let path = format!("{}:{}", first.display(), second.display());
        assert_eq!(find_on_path("rg", &path), Some(first.join("rg")));
    }

    // CLI graduation (0.26.0): the serde default only reaches profiles with
    // the field absent, so existing installs need the one-time flip. The
    // contract worth pinning is that it is ONE time: without the marker check
    // the CLI would switch itself back on at every launch and there would be
    // no way to keep it off.
    #[test]
    fn cli_migration_turns_it_on_for_an_existing_profile_that_had_it_off() {
        let mut s = Settings { cli_enabled: false, cli_default_migrated: false, ..Default::default() };
        assert!(apply_cli_default_migration(&mut s), "should report a change to persist");
        assert!(s.cli_enabled);
        assert!(s.cli_default_migrated, "marker must be stamped so it never re-runs");
    }

    #[test]
    fn cli_migration_never_re_enables_after_the_user_turns_it_off() {
        // The state right after someone switches the CLI off post-migration.
        let mut s = Settings { cli_enabled: false, cli_default_migrated: true, ..Default::default() };
        assert!(!apply_cli_default_migration(&mut s), "must not rewrite settings");
        assert!(!s.cli_enabled, "an explicit opt-out has to survive relaunch");
    }

    #[test]
    fn cli_migration_stamps_a_fresh_profile_without_changing_the_answer() {
        // Fresh install: the serde default already gave us true, but the
        // marker still has to be stamped or the flip stays pending forever.
        let mut s = Settings { cli_enabled: true, cli_default_migrated: false, ..Default::default() };
        assert!(apply_cli_default_migration(&mut s));
        assert!(s.cli_enabled);
        assert!(s.cli_default_migrated);
    }

    // Pinned tabs (GH #183). Task JSON has no migration step: `#[serde(default)]`
    // IS the compatibility story, so a task file written before pinning existed
    // must still load, and a pinned one must survive a save/load round trip.
    #[test]
    fn a_task_file_without_pinned_loads_with_it_off() {
        let t: PersistedTab = serde_json::from_str(r#"{"id":"t1","cli":"claude"}"#).unwrap();
        assert!(!t.pinned);
    }

    #[test]
    fn pinned_survives_a_round_trip() {
        let t = PersistedTab { id: "t1".into(), cli: "claude".into(), pinned: true, ..Default::default() };
        let back: PersistedTab = serde_json::from_str(&serde_json::to_string(&t).unwrap()).unwrap();
        assert!(back.pinned);
    }

    // Scheduled queue messages (GH #300) ride on the tab record.
    #[test]
    fn a_task_file_without_scheduled_loads_with_none() {
        let t: PersistedTab = serde_json::from_str(r#"{"id":"t1","cli":"claude"}"#).unwrap();
        assert!(t.scheduled.is_empty());
        // And an empty set is not written back, so old readers see no change.
        assert!(!serde_json::to_string(&t).unwrap().contains("scheduled"));
    }

    fn input(id: &str, title: &str) -> PersistedTabInput {
        serde_json::from_value(serde_json::json!({ "id": id, "cli": "claude", "title": title })).unwrap()
    }

    #[test]
    fn a_tab_list_rewrite_keeps_each_tabs_schedule_and_session() {
        let msg = ScheduledMessage { id: "m1".into(), text: "check logs".into(), not_before: 1_700_000_000_000, created: 1 };
        let prior = vec![
            PersistedTab { id: "a".into(), cli: "claude".into(), session_id: Some("s-a".into()), scheduled: vec![msg.clone()], ..Default::default() },
            PersistedTab { id: "b".into(), cli: "claude".into(), ..Default::default() },
        ];
        // A rename plus a reorder, and the payload claims a different uuid.
        let mut renamed = input("a", "renamed");
        renamed.session_id = Some("from-payload".into());
        let next = merge_persisted_tabs(&prior, vec![input("b", "b"), renamed], true);
        assert_eq!(next[0].id, "b");
        assert!(next[0].scheduled.is_empty());
        assert_eq!(next[1].title.as_deref(), Some("renamed"));
        assert_eq!(next[1].scheduled, vec![msg]);
        assert_eq!(next[1].session_id.as_deref(), Some("s-a"));
    }

    #[test]
    fn a_tab_dropped_from_the_list_drops_its_schedule() {
        let prior = vec![PersistedTab {
            id: "a".into(), cli: "claude".into(),
            scheduled: vec![ScheduledMessage { id: "m1".into(), text: "x".into(), not_before: 1, created: 1 }],
            ..Default::default()
        }];
        let next = merge_persisted_tabs(&prior, vec![input("c", "c")], true);
        assert_eq!(next.len(), 1);
        assert!(next[0].scheduled.is_empty());
    }

    fn role(kind: &str, task: &str) -> PtyRole {
        PtyRole { task_id: task.into(), tab_id: None, kind: kind.into(), is_default: false }
    }

    // The derived-name bump (GH #153): unnamed repo-root sessions all
    // derive the branch name, and the duplicate guard must adjust those
    // past live twins rather than make the second session impossible.
    #[test]
    fn unique_task_name_bumps_derived_names_past_live_twins() {
        let t = |name: &str, project: &str, archived: bool| Task {
            name: name.into(),
            project_id: project.into(),
            archived,
            ..Task::default()
        };
        let tasks = vec![
            t("main", "p1", false),
            t("main-2", "p1", false),
            t("main", "p2", false),  // other project: never collides
            t("main-3", "p1", true), // archived: reusable
        ];
        // A free name passes through untouched.
        assert_eq!(unique_task_name("solo", &tasks, "p1"), "solo");
        // Taken (case-insensitive) bumps past every LIVE twin; the
        // archived main-3 does not block its own reuse.
        assert_eq!(unique_task_name("Main", &tasks, "p1"), "Main-3");
        // A base already ending in -<n> bumps the number, no nesting.
        assert_eq!(unique_task_name("main-2", &tasks, "p1"), "main-3");
        // Same name, other project: only its own twins count.
        assert_eq!(unique_task_name("main", &tasks, "p2"), "main-2");
    }

    // `termic quit`'s confirmation says "kills N agents across M tasks", and
    // that number is the only thing between a teardown script and every
    // running agent. The PTY map also holds the aux shell, plain shell tabs
    // and setup/run script tabs; counting those as "agents" would inflate the
    // number the user is deciding on.
    #[test]
    fn live_agent_count_counts_agents_only() {
        let a1 = role("agent", "t1");
        let a2 = role("agent", "t1"); // second agent tab, SAME task
        let a3 = role("agent", "t2");
        let aux = role("aux", "t1");
        let slots = vec![
            (true, Some(&a1)),
            (true, Some(&a2)),
            (true, Some(&a3)),
            (true, Some(&aux)),  // aux shell: dies too, but is not an agent
            (true, None),        // setup/run script or plain shell tab
            (false, Some(&a3)),  // already exited: nothing left to kill
        ];
        // 3 live agent tabs across 2 distinct tasks.
        assert_eq!(count_live_agents(slots.into_iter()), (2, 3));
    }

    #[test]
    fn live_agent_count_is_zero_when_only_shells_are_open() {
        let aux = role("aux", "t1");
        let slots = vec![(true, Some(&aux)), (true, None)];
        // Must not report "1 agent across 0 tasks" - the shape the old
        // slot.task_id attribution produced.
        assert_eq!(count_live_agents(slots.into_iter()), (0, 0));
    }

    // The close button routes on a STRING from settings.json. Anything the
    // app does not recognise must fall back to ASKING: quitting kills every
    // running agent, so a corrupt, hand-edited, or future-version settings
    // file must never be able to pick the destructive branch by accident.
    #[test]
    fn close_action_defaults_to_ask_and_never_to_quit() {
        assert_eq!(close_action_from(Some("menubar")), CloseAction::MenuBar);
        assert_eq!(close_action_from(Some("quit")), CloseAction::Quit);
        // Unset (fresh install / upgrade from a build without the field).
        assert_eq!(close_action_from(None), CloseAction::Ask);
        assert_eq!(close_action_from(Some("ask")), CloseAction::Ask);
        // Junk, case variants, and a hypothetical future value all ask.
        for junk in ["", "Quit", "QUIT", "menu bar", "background", "nonsense"] {
            assert_eq!(
                close_action_from(Some(junk)),
                CloseAction::Ask,
                "unrecognised close_action {junk:?} must ask, not act",
            );
        }
    }

    #[test]
    fn keep_in_menu_bar_reenables_a_disabled_tray() {
        // The one case that matters: tray was off, user explicitly asked to
        // keep Termic in the menu bar.
        assert!(should_reenable_tray("menubar", Some(false)));
        // Already on (None = default-on, or explicit true): nothing to do.
        assert!(!should_reenable_tray("menubar", None));
        assert!(!should_reenable_tray("menubar", Some(true)));
        // A disabled tray must stay disabled for any OTHER close action —
        // this is specifically about the "menu bar" button, not a general
        // "any close re-enables it" rule.
        assert!(!should_reenable_tray("quit", Some(false)));
        assert!(!should_reenable_tray("ask", Some(false)));
    }

    #[test]
    fn pty_ring_caps_and_reports_truncation() {
        let mut ring = PtyRing::new();
        ring.push(b"hello ");
        ring.push(b"world");
        let (tail, truncated) = ring.tail(usize::MAX);
        assert_eq!(tail, b"hello world");
        assert!(!truncated);
        // A capped tail flags the drop.
        let (tail, truncated) = ring.tail(5);
        assert_eq!(tail, b"world");
        assert!(truncated);
        // Overflow keeps the newest CAP bytes and flags the drop for good.
        ring.push(&vec![b'x'; PtyRing::CAP]);
        let (tail, truncated) = ring.tail(usize::MAX);
        assert_eq!(tail.len(), PtyRing::CAP);
        assert!(tail.iter().all(|b| *b == b'x'));
        assert!(truncated);
        // A single chunk larger than the cap keeps only its tail.
        let mut ring = PtyRing::new();
        let mut big = vec![b'a'; PtyRing::CAP];
        big.extend_from_slice(b"end");
        ring.push(&big);
        let (tail, truncated) = ring.tail(usize::MAX);
        assert_eq!(tail.len(), PtyRing::CAP);
        assert!(tail.ends_with(b"end"));
        assert!(truncated);
    }

    #[test]
    fn wait_for_attach_returns_as_soon_as_the_webview_acks() {
        // The normal path: the flusher parks, the ack lands a moment later,
        // output flows. Nothing may wait out the grace here.
        let buf: Arc<(Mutex<Vec<u8>>, Condvar)> = Arc::new((Mutex::new(Vec::new()), Condvar::new()));
        let attached = Arc::new(AtomicBool::new(false));
        let done = Arc::new(AtomicBool::new(false));
        let b2 = buf.clone();
        let a2 = attached.clone();
        thread::spawn(move || {
            thread::sleep(Duration::from_millis(50));
            let _g = b2.0.lock();
            a2.store(true, Ordering::Release);
            b2.1.notify_all();
        });
        let t0 = Instant::now();
        wait_for_attach(&buf, &attached, &done, Duration::from_secs(30));
        assert!(t0.elapsed() < Duration::from_secs(5), "took {:?}", t0.elapsed());
    }

    #[test]
    fn wait_for_attach_gives_up_after_the_grace() {
        // A caller that never acks must not wedge its PTY forever: output is
        // late, not lost.
        let buf: Arc<(Mutex<Vec<u8>>, Condvar)> = Arc::new((Mutex::new(Vec::new()), Condvar::new()));
        let attached = Arc::new(AtomicBool::new(false));
        let done = Arc::new(AtomicBool::new(false));
        let t0 = Instant::now();
        wait_for_attach(&buf, &attached, &done, Duration::from_millis(120));
        assert!(t0.elapsed() >= Duration::from_millis(100), "returned early: {:?}", t0.elapsed());
        assert!(t0.elapsed() < Duration::from_secs(5), "overshot: {:?}", t0.elapsed());
    }

    #[test]
    fn wait_for_attach_returns_when_the_process_dies_first() {
        // The reader's final drain waits on this too, so a child that exits
        // before the ack must not hold pty-exit for the whole grace.
        let buf: Arc<(Mutex<Vec<u8>>, Condvar)> = Arc::new((Mutex::new(Vec::new()), Condvar::new()));
        let attached = Arc::new(AtomicBool::new(false));
        let done = Arc::new(AtomicBool::new(true));
        let t0 = Instant::now();
        wait_for_attach(&buf, &attached, &done, Duration::from_secs(30));
        assert!(t0.elapsed() < Duration::from_secs(1), "took {:?}", t0.elapsed());
    }

    #[test]
    fn pty_feed_tap_gets_backlog_then_live_data_exactly_once() {
        let feed = PtyFeed::new();
        feed.push(b"before");
        let (backlog, truncated, rx, session_tx) = feed.subscribe();
        assert_eq!(backlog, b"before");
        assert!(!truncated);
        feed.push(b"after");
        match rx.recv_timeout(std::time::Duration::from_secs(1)) {
            Ok(PtyTapMsg::Data(d)) => assert_eq!(d, b"after"),
            other => panic!("expected live data, got {:?}", other.is_ok()),
        }
        // No duplicate of the backlog on the live channel.
        assert!(rx.try_recv().is_err());
        // A detach reaches the tap in-band, from the feed AND from the
        // session's own sender clone (the input thread's path).
        feed.send_detach("archived");
        match rx.recv_timeout(std::time::Duration::from_secs(1)) {
            Ok(PtyTapMsg::Detach(r)) => assert_eq!(r, "archived"),
            other => panic!("expected detach, got {:?}", other.is_ok()),
        }
        session_tx.send(PtyTapMsg::Detach("detached".into())).unwrap();
        match rx.recv_timeout(std::time::Duration::from_secs(1)) {
            Ok(PtyTapMsg::Detach(r)) => assert_eq!(r, "detached"),
            other => panic!("expected detach, got {:?}", other.is_ok()),
        }
        drop(rx);
        drop(session_tx);
        feed.push(b"into the void");
        assert!(feed.inner.lock().taps.is_empty(), "dead taps must be pruned");
    }

    fn mkrepo(base: &Path, rel: &str) {
        fs::create_dir_all(base.join(rel).join(".git")).unwrap();
    }
    fn discovered_names(dir: &Path) -> std::collections::HashSet<String> {
        discover_repos_in(&ProfileId::Root, dir.to_string_lossy().into_owned())
            .unwrap()
            .into_iter()
            .map(|r| r.name)
            .collect()
    }

    #[test]
    fn discover_repos_flat_layout() {
        let root = tempdir().unwrap();
        mkrepo(root.path(), "repo-a");
        mkrepo(root.path(), "repo-b");
        assert_eq!(discovered_names(root.path()), ["repo-a", "repo-b"].map(String::from).into());
    }

    #[test]
    fn discover_repos_flags_dismissed() {
        let root = tempdir().unwrap();
        mkrepo(root.path(), "keep");
        mkrepo(root.path(), "hide");
        let hide_canon = dunce::canonicalize(root.path().join("hide"))
            .unwrap().to_string_lossy().into_owned();
        let dismissed: std::collections::HashSet<String> = [hide_canon].into();
        let repos = discover_repos_inner(root.path(), &Default::default(), &dismissed).unwrap();
        assert!(repos.iter().find(|r| r.name == "hide").unwrap().dismissed);
        assert!(!repos.iter().find(|r| r.name == "keep").unwrap().dismissed);
    }

    #[test]
    fn discover_repos_two_level_grouping() {
        let root = tempdir().unwrap();
        mkrepo(root.path(), "work/repo-c");
        mkrepo(root.path(), "oss/repo-d");
        assert_eq!(discovered_names(root.path()), ["repo-c", "repo-d"].map(String::from).into());
    }

    #[test]
    fn default_worktree_symlink_paths_carries_mcp_json() {
        // GH #251: `.mcp.json` holds project-scoped MCP servers and is
        // commonly gitignored, exactly like `.claude/`, so a plain worktree
        // checkout silently loses them.
        let d = default_worktree_symlink_paths();
        assert!(d.contains(&".mcp.json".to_string()), "{d:?}");
        assert!(d.contains(&".claude".to_string()), "{d:?}");
    }

    #[test]
    fn link_config_dir_links_a_file_not_just_a_dir() {
        // The list is no longer dirs-only. A file entry must link like any
        // other, or `.mcp.json` is in the default and does nothing.
        let repo = tempdir().unwrap();
        fs::create_dir_all(repo.path().join(".git/info")).unwrap();
        fs::write(repo.path().join(".mcp.json"), b"{\"mcpServers\":{}}").unwrap();
        fs::create_dir_all(repo.path().join(".claude")).unwrap();
        let wt = tempdir().unwrap();

        link_config_dir(repo.path(), wt.path(), ".mcp.json");
        link_config_dir(repo.path(), wt.path(), ".claude");

        let linked = wt.path().join(".mcp.json");
        assert!(linked.symlink_metadata().unwrap().file_type().is_symlink());
        assert_eq!(fs::read_to_string(&linked).unwrap(), "{\"mcpServers\":{}}");
        assert!(wt.path().join(".claude").symlink_metadata().unwrap().file_type().is_symlink());
        // A name the repo lacks is a no-op, not an error or a broken link.
        link_config_dir(repo.path(), wt.path(), ".gemini");
        assert!(wt.path().join(".gemini").symlink_metadata().is_err());
    }

    #[test]
    fn mcp_json_upgrade_only_touches_an_unedited_list() {
        // An untouched list is the "pre-filled starting point" and may gain
        // the new entry; anything the user shaped is theirs.
        let untouched: Settings =
            serde_json::from_str(r#"{"worktree_symlink_paths":[".claude",".gemini",".codex"]}"#).unwrap();
        assert_eq!(untouched.worktree_symlink_paths, legacy_worktree_symlink_paths_v0_29());

        // Edited (an entry removed), cleared, and extended lists must all
        // survive the upgrade untouched — the migration compares for EQUALITY
        // with the old default precisely so it cannot overwrite a choice.
        for stored in [
            vec![".claude".to_string()],
            vec![],
            vec![".claude".into(), ".gemini".into(), ".codex".into(), ".envrc".into()],
        ] {
            assert_ne!(stored, legacy_worktree_symlink_paths_v0_29(), "{stored:?}");
            assert_ne!(stored, legacy_worktree_symlink_paths_v1_3(), "{stored:?}");
        }

        // The `.mcp.json`-era default is the OTHER untouched shape: a user who
        // upgraded through that release and never edited the list must still
        // be recognised, or `.devin` never reaches them.
        let untouched_v1_3: Settings = serde_json::from_str(
            r#"{"worktree_symlink_paths":[".claude",".gemini",".codex",".mcp.json"]}"#,
        )
        .unwrap();
        assert_eq!(untouched_v1_3.worktree_symlink_paths, legacy_worktree_symlink_paths_v1_3());
        // And the new default really is that list plus one entry, so the
        // upgrade is an append rather than a rewrite.
        let mut expected = legacy_worktree_symlink_paths_v1_3();
        expected.push(".devin".into());
        assert_eq!(default_worktree_symlink_paths(), expected);
    }

    #[test]
        fn worktree_symlink_paths_absent_vs_cleared() {
        // Absent in an old settings.json -> pre-filled defaults, so upgraders
        // keep the original .claude-linking behavior instead of silently losing it.
        let absent: Settings = serde_json::from_str("{}").unwrap();
        assert_eq!(absent.worktree_symlink_paths, default_worktree_symlink_paths());
        assert!(!absent.worktree_symlink_paths.is_empty());
        // Present-but-empty -> respected: a user who cleared the list to disable
        // the linking must NOT get the defaults forced back on.
        let cleared: Settings = serde_json::from_str(r#"{"worktree_symlink_paths":[]}"#).unwrap();
        assert!(cleared.worktree_symlink_paths.is_empty());
        // Explicit list -> used verbatim.
        let custom: Settings = serde_json::from_str(r#"{"worktree_symlink_paths":[".claude",".foo"]}"#).unwrap();
        assert_eq!(custom.worktree_symlink_paths, vec![".claude".to_string(), ".foo".to_string()]);
        // New installs + corrupt files seed the pre-filled defaults, NOT an
        // empty vec. `load_settings_inner`'s fallback arms both use
        // seeded_defaults(); this is the exact expression the corrupt-file arm
        // runs (simion's catch: bare Settings::default() would birth the linking
        // permanently off).
        assert_eq!(seeded_defaults().worktree_symlink_paths, default_worktree_symlink_paths());
        let corrupt: Settings = serde_json::from_str("not valid json").unwrap_or_else(|_| seeded_defaults());
        assert_eq!(corrupt.worktree_symlink_paths, default_worktree_symlink_paths());
    }

    // Grok 1.0.5 supports the same deterministic-session pair claude does.
    // Verified against a live binary: `-s <uuid>` minted a session and
    // `-r <uuid>` resumed it. Pinned because these were empty for long enough
    // that every grok task fell back to cwd-based `--continue`, which grabs an
    // unrelated session when two tasks share a repo root.
    /// Termic is routinely launched FROM an agent, and it copied that
    /// session's identity into every agent it spawned: the child believed it
    /// was a child (transcript saving off), adopted the launcher's session id
    /// (an agent in one repo reaching for another), and was handed a live
    /// messaging socket and token for it while caged.
    #[test]
    fn another_agent_session_is_not_inherited_by_a_spawn() {
        for k in [
            "CLAUDECODE",
            "CLAUDE_CODE_CHILD_SESSION",
            "CLAUDE_CODE_SESSION_ID",
            "CLAUDE_CODE_BRIDGE_SESSION_ID",
            "CLAUDE_CODE_MESSAGING_SOCKET",
            "CLAUDE_CODE_MESSAGING_TOKEN",
            "CLAUDE_PID",
            "CHISEL_SESSION_DB",
        ] {
            assert!(agent_session_marker(k), "{k} must not reach a spawned agent");
        }
        // NOT swept: the user's own settings. `CLAUDE_CONFIG_DIR` is how a
        // cloned agent holds a second account, and dropping it would point
        // that clone back at the first one's login. A prefix match would.
        for k in ["CLAUDE_CONFIG_DIR", "ANTHROPIC_API_KEY", "CLAUDE_CODE_NO_FLICKER", "PATH"] {
            assert!(!agent_session_marker(k), "{k} must still be inherited");
        }
    }

    #[test]
    fn grok_has_id_based_resume_args() {
        let agents = seeded_defaults().agents;
        let grok = agents.iter().find(|a| a.id == "grok").expect("grok seeded");
        assert_eq!(grok.capabilities.session_id_args, vec!["--session-id", "{UUID}"]);
        assert_eq!(grok.capabilities.resume_id_args, vec!["--resume", "{UUID}"]);
        // The cwd-based fallback stays for tasks minted before id resume.
        assert_eq!(grok.capabilities.resume_args, vec!["--continue"]);
        assert_eq!(grok.capabilities.yolo_args, vec!["--always-approve"]);
        // grok has no --name flag; leaving this non-empty would break spawns.
        assert!(grok.capabilities.name_args.is_empty());
    }

    // pi (pi.dev) 0.84.3, verified against a live binary rather than --help.
    // Its one oddity is that --session-id both MINTS and RESUMES ("creating it
    // if missing"), so the two arg lists are deliberately identical; a reviewer
    // seeing that duplication should not "fix" it into claude's two-flag shape.
    #[test]
    fn pi_uses_one_flag_for_both_mint_and_resume() {
        let agents = seeded_defaults().agents;
        let pi = agents.iter().find(|a| a.id == "pi").expect("pi seeded");
        assert_eq!(pi.capabilities.session_id_args, vec!["--session-id", "{UUID}"]);
        assert_eq!(pi.capabilities.resume_id_args, vec!["--session-id", "{UUID}"]);
        assert_eq!(pi.capabilities.resume_args, vec!["--continue"]);
        assert_eq!(pi.capabilities.name_args, vec!["--name", "{WORKSPACE_SLUG}"]);
        // pi asks for no tool approval in default mode, so there is no flag to
        // pass. Empty here is a measured fact, not an unfinished entry.
        assert!(pi.capabilities.yolo_args.is_empty());
        // Sessions live under ~/.pi, which the cage has to reach.
        assert!(pi.sandbox_allowed_paths.iter().any(|p| p.contains(".pi")));
        assert_eq!(pi.icon_id, "pi");
        // pi mints deterministically, so it must NOT use opencode's
        // post-exit capture path.
        assert!(pi.post_launch_capture.is_none());
    }

    // Muse Code 1.0.2, measured against a live binary via its offline
    // `--provider echo`. The entry a reviewer is most likely to want to
    // "finish" is the empty id-resume pair, so this pins WHY it is empty:
    // `--session-id` is an `exec`-only flag and the TUI rejects it, so there
    // is no way to mint a termic-owned session for an interactive spawn. Do
    // not copy claude's two-flag shape in here.
    #[test]
    fn muse_resumes_by_captured_id_and_cannot_mint_a_session() {
        let agents = seeded_defaults().agents;
        let muse = agents.iter().find(|a| a.id == "muse").expect("muse seeded");
        assert_eq!(muse.capabilities.resume_args, vec!["resume", "--last"]);
        // No MINT: `--session-id` is an `exec` flag and the TUI rejects it, so
        // termic can never hand muse an id at launch. That is the half that
        // stays empty; `resume_id_args` is not, because muse can resume an id
        // it chose itself (see the capture below).
        assert!(muse.capabilities.session_id_args.is_empty());
        // No --name equivalent in muse's help.
        assert!(muse.capabilities.name_args.is_empty());
        // One flag drops approval AND muse's own sandbox AND the trust prompt.
        assert_eq!(muse.capabilities.yolo_args, vec!["--yolo"]);
        // Auth lives in ~/.config/muse, sessions in ~/.local/share/muse; the
        // cage needs both or `resume --last` finds nothing.
        assert!(muse.sandbox_allowed_paths.iter().any(|p| p.ends_with(".config/muse")));
        assert!(muse.sandbox_allowed_paths.iter().any(|p| p.ends_with(".local/share/muse")));
        // macOS state, WRITTEN on every launch. Its absence is not a
        // degradation, it is muse refusing to start under the cage.
        assert!(
            muse.sandbox_allowed_paths.iter()
                .any(|p| p == "$HOME/Library/Application Support/Muse"),
            "muse writes ~/Library/Application Support/Muse/session-name-authority on launch"
        );
        // NOT granted, and deliberately: muse reads other agents' config as
        // "foreign personal context", and termic handing a muse task the
        // user's codex config would be a cross-agent leak the user never
        // asked for. It has its own flag for that (`--no-foreign-personal-context`).
        assert!(
            !muse.sandbox_allowed_paths.iter().any(|p| p.contains(".codex")),
            "muse must not be granted another agent's config dir"
        );
        // ~/.local/bin is the SHARED install dir (claude, agy, grok and codex
        // all keep a binary or shim there) and these paths grant `file-write*`,
        // so muse gets a regex over its own files rather than the directory.
        // Granting the subpath would let a muse task overwrite another agent's
        // binary.
        assert!(
            !muse.sandbox_allowed_paths.iter().any(|p| p == "$HOME/.local/bin"),
            "muse must not be granted write over the whole shared bin dir"
        );
        let bin_rule = muse.sandbox_allowed_paths.iter()
            .find(|p| p.contains(".local/bin"))
            .expect("muse still needs its own files in the install dir");
        assert!(bin_rule.starts_with("regex:"), "must be scoped, got {bin_rule}");
        for f in ["muse", "muse-bin-1.0.2-R2040.1", ".muse-version", ".muse-update-checked-at"] {
            assert!(
                regex::Regex::new(&bin_rule["regex:".len()..].replace("$HOME", "/Users/u"))
                    .unwrap()
                    .is_match(&format!("/Users/u/.local/bin/{f}")),
                "muse's own {f} must stay writable"
            );
        }
        for f in ["claude", "codex", "agy", "grok", "amusement"] {
            assert!(
                !regex::Regex::new(&bin_rule["regex:".len()..].replace("$HOME", "/Users/u"))
                    .unwrap()
                    .is_match(&format!("/Users/u/.local/bin/{f}")),
                "{f} is another agent's binary and must NOT be writable by muse"
            );
        }
        assert_eq!(muse.icon_id, "muse");
        // It CAN resume a specific session, it just cannot be handed the id at
        // launch, so the id is captured off disk afterwards (opencode's shape).
        assert_eq!(muse.capabilities.resume_id_args, vec!["resume", "{UUID}"]);
        let cap = muse.post_launch_capture.as_ref().expect("muse captures its session id");
        // The shape that makes it work, spelled out because each part is load
        // bearing: newest-first (`-t`), directories four levels down
        // (YYYY/MM/DD/<uuid>), XDG-aware, and quiet when there are none yet.
        assert!(cap.command.contains("muse/sessions"), "{}", cap.command);
        assert!(cap.command.contains("XDG_DATA_HOME"), "{}", cap.command);
        assert!(cap.command.contains("/*/*/*/*/"), "{}", cap.command);
        assert!(cap.command.contains("-td"), "newest first: {}", cap.command);
        assert!(cap.command.contains("2>/dev/null"), "quiet when absent: {}", cap.command);
        // The line continuation above must not have eaten the separating
        // space; without it the glob and the redirect fuse into one word.
        assert!(!cap.command.contains("/*/2>"), "lost a space: {}", cap.command);
    }

    // Devin (Cognition) 3000.10.21, verified against a live binary rather than
    // --help. Its one structural difference from the agents above: session ids
    // are devin-minted slugs (`brassy-polish`), never uuids, so termic cannot
    // mint one and `-r` takes the slug verbatim.
    #[test]
    fn devin_resumes_by_captured_slug_and_cannot_mint_a_session() {
        let agents = seeded_defaults().agents;
        let devin = agents.iter().find(|a| a.id == "devin").expect("devin seeded");
        assert_eq!(devin.capabilities.resume_args, vec!["--continue"]);
        // No MINT: nothing accepts an id at launch. The id arrives from
        // termic's SessionStart hook, with `devin list` as the capture
        // backstop, which is the capture shape and why resume_id_args is set.
        assert!(devin.capabilities.session_id_args.is_empty());
        assert_eq!(devin.capabilities.resume_id_args, vec!["--resume", "{UUID}"]);
        // No --name flag in devin's help.
        assert!(devin.capabilities.name_args.is_empty());
        assert_eq!(devin.capabilities.yolo_args, vec!["--permission-mode", "dangerous"]);
        // The title moves through `devin: <dir>` / `devin: <prompt>` /
        // `devin: <generated title>` with no working/attention marker, and no
        // OSC 9 at all: empty signals is a measured fact, not a gap.
        assert!(devin.capabilities.signals.attention.is_empty());
        assert!(devin.capabilities.signals.busy.is_empty());
        assert!(devin.capabilities.signals.idle.is_empty());
        assert!(devin.capabilities.signals.pending.is_empty());
        // Config + credentials + the session database + the CLI's own
        // versioned binaries all live under these roots; the cage needs every
        // one or login and resume silently break inside it.
        for p in [".config/devin", ".local/share/devin", ".devin", ".cache/devin"] {
            assert!(devin.sandbox_allowed_paths.iter().any(|x| x.ends_with(p)),
                "devin needs {p} writable");
        }
        // The binary shim shares ~/.local/bin with every other agent, so it
        // gets a scoped regex rather than the directory.
        assert!(!devin.sandbox_allowed_paths.iter().any(|p| p == "$HOME/.local/bin"),
            "devin must not be granted write over the whole shared bin dir");
        let bin_rule = devin.sandbox_allowed_paths.iter()
            .find(|p| p.contains(".local/bin"))
            .expect("devin still needs its own shim in the install dir");
        assert!(bin_rule.starts_with("regex:"), "must be scoped, got {bin_rule}");
        let re = regex::Regex::new(&bin_rule["regex:".len()..].replace("$HOME", "/Users/u")).unwrap();
        assert!(re.is_match("/Users/u/.local/bin/devin"), "devin's own shim must stay writable");
        for f in ["claude", "codex", "muse", "devin-bin-x"] {
            assert!(!re.is_match(&format!("/Users/u/.local/bin/{f}")),
                "{f} is not devin's shim and must NOT be writable by devin");
        }
        assert_eq!(devin.icon_id, "devin");
        let cap = devin.post_launch_capture.as_ref().expect("devin captures its session slug");
        // `devin list --format csv`: header row, then this cwd's sessions
        // newest-first. A bare `devin list` is an interactive picker, which is
        // why the capture names the format.
        assert!(cap.command.contains("devin list --format csv"), "{}", cap.command);
        assert!(cap.command.contains("cut -d, -f1"), "{}", cap.command);
    }

    #[test]
    fn discover_repos_mixed_top_repo_and_grouping() {
        let root = tempdir().unwrap();
        mkrepo(root.path(), "top-repo");
        mkrepo(root.path(), "work/nested-repo");
        assert_eq!(discovered_names(root.path()), ["top-repo", "nested-repo"].map(String::from).into());
    }

    #[test]
    fn discover_repos_nested_clone_not_descended() {
        // A repo child is taken as-is; its own subdirs (vendored clones) must
        // NOT be scanned as separate repos.
        let root = tempdir().unwrap();
        mkrepo(root.path(), "repo-a");
        mkrepo(root.path(), "repo-a/vendor/inner");
        assert_eq!(discovered_names(root.path()), ["repo-a"].map(String::from).into());
    }

    #[test]
    #[cfg(unix)]
    fn discover_repos_dedups_symlink_reachable_twice() {
        // A `self -> .` symlink makes the whole root reachable a second time as
        // a grouping folder (the real-world `~/r -> Work/Repos` case). Canonical
        // -path dedup must keep each repo once, not list it twice.
        let root = tempdir().unwrap();
        mkrepo(root.path(), "repo-a");
        mkrepo(root.path(), "repo-b");
        std::os::unix::fs::symlink(root.path(), root.path().join("all")).unwrap();
        let repos = discover_repos_in(&ProfileId::Root, root.path().to_string_lossy().into_owned()).unwrap();
        let names: Vec<_> = repos.iter().map(|r| r.name.clone()).collect();
        assert_eq!(repos.len(), 2, "each repo should appear once, got {names:?}");
    }

    #[test]
    fn discover_repos_skips_hidden_and_node_modules() {
        let root = tempdir().unwrap();
        mkrepo(root.path(), "work/real");
        mkrepo(root.path(), "work/node_modules/pkg");
        mkrepo(root.path(), "work/.cache/hidden");
        // A top-level hidden dir that is itself a repo is skipped too.
        mkrepo(root.path(), ".dotfiles");
        assert_eq!(discovered_names(root.path()), ["real"].map(String::from).into());
    }

    #[test]
    fn safe_task_path_allows_contained_files() {
        let dir = tempdir().unwrap();
        fs::create_dir_all(dir.path().join("docs")).unwrap();
        fs::write(dir.path().join("docs/a.png"), b"x").unwrap();
        let p = safe_task_path(dir.path(), "docs/a.png").unwrap();
        assert!(p.ends_with("docs/a.png"));
    }

    #[test]
    fn safe_task_path_rejects_absolute_and_parent_segments() {
        let dir = tempdir().unwrap();
        assert!(safe_task_path(dir.path(), "/etc/passwd").is_err());
        assert!(safe_task_path(dir.path(), "../outside.txt").is_err());
        assert!(safe_task_path(dir.path(), "docs/../../outside.txt").is_err());
    }

    #[cfg(unix)]
    #[test]
    fn safe_task_path_rejects_symlink_escape() {
        // A symlink INSIDE the worktree pointing OUTSIDE must fail the
        // canonicalized containment check (the markdown preview reads
        // whatever path a hostile README references).
        let outside = tempdir().unwrap();
        fs::write(outside.path().join("secret.png"), b"x").unwrap();
        let ws = tempdir().unwrap();
        std::os::unix::fs::symlink(outside.path().join("secret.png"), ws.path().join("link.png")).unwrap();
        let err = safe_task_path(ws.path(), "link.png").unwrap_err();
        // The message has to name where the link went, or the file tree row it
        // ends up in is as unactionable as the one #250 reported.
        assert!(err.contains("path escapes task: link.png -> "), "{err}");
        assert!(err.contains("secret.png"), "{err}");
    }

    // ───────── linked config dirs in a worktree (GH #250) ─────────

    /// A repo with a gitignored `.claude/`, plus a worktree carrying the
    /// symlink `link_config_dir` creates into it. This is the exact shape a
    /// real task has, and the shape the strict check refused to read.
    fn repo_with_linked_config() -> (tempfile::TempDir, tempfile::TempDir) {
        let repo = tempdir().unwrap();
        fs::create_dir_all(repo.path().join(".claude/agents")).unwrap();
        fs::write(repo.path().join(".claude/settings.json"), b"{}").unwrap();
        let wt = tempdir().unwrap();
        crate::fs_link::symlink_any(
            fs::canonicalize(repo.path().join(".claude")).unwrap(),
            wt.path().join(".claude"),
        )
        .unwrap();
        (repo, wt)
    }

    #[test]
    fn reads_through_the_config_symlink_termic_created() {
        let (repo, wt) = repo_with_linked_config();
        // The bug: we make this link because .claude is gitignored, then the
        // strict check refuses to read back through it, so the folder lists
        // and never opens.
        assert!(safe_task_path(wt.path(), ".claude").is_err());

        let dir = safe_task_read_path_in(Some(repo.path()), wt.path(), ".claude").unwrap();
        assert_eq!(dir, dunce::canonicalize(repo.path().join(".claude")).unwrap());
        // …and files under it, which is what the editor opens.
        let file = safe_task_read_path_in(Some(repo.path()), wt.path(), ".claude/settings.json").unwrap();
        assert!(file.ends_with(".claude/settings.json"));
        assert!(safe_task_read_path_in(Some(repo.path()), wt.path(), ".claude/agents").is_ok());
    }

    #[cfg(unix)]
    #[test]
    fn still_refuses_a_link_that_leaves_the_project() {
        // The case the containment check exists for: a repo shipping a link to
        // something private. It resolves outside the PROJECT root, so widening
        // the bound to the project must not admit it.
        let (repo, wt) = repo_with_linked_config();
        let outside = tempdir().unwrap();
        fs::create_dir_all(outside.path().join("ssh")).unwrap();
        fs::write(outside.path().join("ssh/id_rsa"), b"secret").unwrap();
        std::os::unix::fs::symlink(
            fs::canonicalize(outside.path().join("ssh")).unwrap(),
            wt.path().join(".secrets"),
        )
        .unwrap();

        let err = safe_task_read_path_in(Some(repo.path()), wt.path(), ".secrets/id_rsa").unwrap_err();
        assert!(err.contains("path escapes task"), "{err}");
        // And with no project known, nothing is relaxed at all.
        assert!(safe_task_read_path_in(None, wt.path(), ".claude").is_err());
    }

    #[cfg(unix)]
    #[test]
    fn only_a_link_at_the_task_root_is_relaxed() {
        // A symlink buried deep in the repo must not widen the check, even
        // when its target is inside the project: only the top-level dirs
        // link_config_dir creates qualify.
        let repo = tempdir().unwrap();
        fs::create_dir_all(repo.path().join("vendor")).unwrap();
        fs::write(repo.path().join("vendor/lib.rs"), b"x").unwrap();
        let wt = tempdir().unwrap();
        fs::create_dir_all(wt.path().join("src/nested")).unwrap();
        std::os::unix::fs::symlink(
            fs::canonicalize(repo.path().join("vendor")).unwrap(),
            wt.path().join("src/nested/vendor"),
        )
        .unwrap();

        assert!(safe_task_read_path_in(Some(repo.path()), wt.path(), "src/nested/vendor/lib.rs").is_err());
    }

    #[test]
    fn ordinary_paths_are_untouched() {
        // The relaxation is a FALLBACK: everything that resolved before still
        // resolves the same way, and the classic escapes stay rejected.
        let (repo, wt) = repo_with_linked_config();
        fs::create_dir_all(wt.path().join("docs")).unwrap();
        fs::write(wt.path().join("docs/a.md"), b"x").unwrap();
        assert_eq!(
            safe_task_read_path_in(Some(repo.path()), wt.path(), "docs/a.md").unwrap(),
            safe_task_path(wt.path(), "docs/a.md").unwrap(),
        );
        assert!(safe_task_read_path_in(Some(repo.path()), wt.path(), "../outside.txt").is_err());
        assert!(safe_task_read_path_in(Some(repo.path()), wt.path(), "/etc/passwd").is_err());
    }

    // ─────────────────── scratchpads (GH #244) ───────────────────

    #[test]
    fn safe_task_path_for_create_allows_a_missing_target_and_missing_parents() {
        let ws = tempdir().unwrap();
        fs::create_dir_all(ws.path().join("docs")).unwrap();
        // Existing folder, new file.
        let p = safe_task_path_for_create(ws.path(), "docs/notes.md").unwrap();
        assert_eq!(p, dunce::canonicalize(ws.path()).unwrap().join("docs/notes.md"));
        // Neither the folder nor the file exists yet: the picker lets you type
        // a new one, and promote mkdir -p's it.
        let p = safe_task_path_for_create(ws.path(), "a/b/c/notes.md").unwrap();
        assert_eq!(p, dunce::canonicalize(ws.path()).unwrap().join("a/b/c/notes.md"));
    }

    #[cfg(unix)]
    #[test]
    fn safe_task_path_for_create_rejects_escapes_including_through_a_symlink() {
        let outside = tempdir().unwrap();
        let ws = tempdir().unwrap();
        assert!(safe_task_path_for_create(ws.path(), "../escape.md").is_err());
        assert!(safe_task_path_for_create(ws.path(), "/etc/passwd").is_err());
        assert!(safe_task_path_for_create(ws.path(), "").is_err());
        // The dangerous case a naive "does the string contain .. ?" check
        // misses: an EXISTING in-worktree directory symlinked outside, with
        // the new file hung underneath it. The target itself never exists, so
        // `safe_task_path` cannot answer this at all.
        std::os::unix::fs::symlink(outside.path(), ws.path().join("out")).unwrap();
        let err = safe_task_path_for_create(ws.path(), "out/notes.md").unwrap_err();
        assert!(err.contains("path escapes task: out/notes.md -> "), "{err}");
    }

    // ARCHIVING A TASK MUST LEAVE ITS PADS ALONE. Archiving is recoverable
    // (the task stays in History, the branch stays in git), and notes about
    // the work are exactly what someone wants back when they restore it. The
    // only place pads may be destroyed is `delete_task_file`, the hard delete
    // behind History's "Empty archive" and project removal.
    //
    // A source guard rather than a behavioural test because the alternative
    // is standing up a real worktree to drive `task_archive_sync`, and what
    // actually needs pinning is the call site, not the deletion.
    #[test]
    fn only_the_hard_delete_purges_scratchpads() {
        let src = include_str!("lib.rs");
        let calls: Vec<&str> = src
            .lines()
            .map(str::trim)
            .filter(|l| l.contains("scratch_purge_task(") && !l.starts_with("//"))
            .collect();
        // Drop this test's own mentions of the name; what is left is the
        // definition plus every real call site.
        let real: Vec<&&str> = calls.iter()
            .filter(|l| !l.starts_with("assert") && !l.contains("l.contains("))
            .collect();
        assert_eq!(
            real.len(), 2,
            "scratch_purge_task gained a call site: {real:#?}\n\
             Only delete_task_file may purge pads — archiving must not.",
        );
        assert!(real.iter().any(|l| l.starts_with("fn scratch_purge_task")), "{real:#?}");
        assert!(real.iter().any(|l| l.starts_with("scratch_purge_task(id);")), "{real:#?}");
        // And that one call really does sit inside delete_task_file.
        let body = src
            .split_once("fn delete_task_file(").expect("delete_task_file exists").1;
        let body = &body[..body.find("\n}\n").expect("function ends")];
        assert!(body.contains("scratch_purge_task(id);"), "delete_task_file no longer purges pads");
    }

    #[test]
    fn scratch_id_ok_refuses_path_segments() {
        assert!(scratch_id_ok("2f1c9b4e-0000-4aaa-bbbb-cccccccccccc"));
        assert!(scratch_id_ok("pad_1"));
        // Every one of these would become a path segment under global_dir().
        for bad in ["", "..", "a/b", "a\\b", "a.txt", "../../etc/passwd", "a b"] {
            assert!(!scratch_id_ok(bad), "{bad:?} must be refused");
        }
        assert!(!scratch_id_ok(&"a".repeat(129)));
    }

    // The index is the only record of a pad's title and syntax — there is no
    // filename to re-derive them from — so a round-trip through it is the
    // whole restore path.
    #[test]
    fn scratch_index_round_trips_and_orders() {
        let recs = vec![
            ScratchRecord { id: "b".into(), title: "second".into(), syntax: Some("json".into()),
                            order: 1, created_at: "t0".into(), updated_at: "t1".into() },
            ScratchRecord { id: "a".into(), title: "first".into(), syntax: None,
                            order: 0, created_at: "t0".into(), updated_at: "t0".into() },
        ];
        let json = serde_json::to_string(&recs).unwrap();
        let mut back: Vec<ScratchRecord> = serde_json::from_str(&json).unwrap();
        back.sort_by_key(|r| r.order);
        assert_eq!(back.iter().map(|r| r.id.as_str()).collect::<Vec<_>>(), ["a", "b"]);
        assert_eq!(back[1].syntax.as_deref(), Some("json"));
        assert_eq!(back[0].syntax, None);
        // Records written before a field existed must still load: a pad that
        // fails to deserialize is a note the user loses.
        let old: Vec<ScratchRecord> = serde_json::from_str(
            r#"[{"id":"a","title":"t","created_at":"x","updated_at":"y"}]"#,
        ).unwrap();
        assert_eq!(old[0].order, 0);
        assert_eq!(old[0].syntax, None);
    }

    #[test]
    fn safe_task_path_names_the_missing_path() {
        // "No such file or directory (os error 2)" alone tells a user nothing
        // about WHICH path is missing (GH #250).
        let ws = tempdir().unwrap();
        let err = safe_task_path(ws.path(), "docs/gone").unwrap_err();
        assert!(err.replace('\\', "/").contains("docs/gone"), "{err}");
        // ENOENT is 2; Windows reports a missing PARENT as 3 (path not found).
        assert!(err.contains("os error 2") || err.contains("os error 3"), "{err}");
    }

    #[test]
    fn check_task_path_existence_reports_missing_for_nonexistent_contained_path() {
        let dir = tempdir().unwrap();
        fs::create_dir_all(dir.path().join("docs")).unwrap();
        let stat = check_task_path_existence(dir.path(), "docs/missing.png").unwrap();
        assert!(!stat.exists);
        assert!(!stat.is_dir);
    }

    #[test]
    fn check_task_path_existence_handles_missing_parent_dirs_too() {
        // The whole ancestor chain (not just the leaf) can be missing —
        // the walk-up must reach ws_path itself, not just the immediate parent.
        let dir = tempdir().unwrap();
        let stat = check_task_path_existence(dir.path(), "a/b/c/missing.png").unwrap();
        assert!(!stat.exists);
    }

    #[test]
    fn check_task_path_existence_reports_existing_file_and_dir() {
        let dir = tempdir().unwrap();
        fs::create_dir_all(dir.path().join("docs")).unwrap();
        fs::write(dir.path().join("docs/a.png"), b"x").unwrap();
        let file_stat = check_task_path_existence(dir.path(), "docs/a.png").unwrap();
        assert!(file_stat.exists);
        assert!(!file_stat.is_dir);
        let dir_stat = check_task_path_existence(dir.path(), "docs").unwrap();
        assert!(dir_stat.exists);
        assert!(dir_stat.is_dir);
    }

    #[test]
    fn check_task_path_existence_rejects_absolute_and_parent_segments() {
        let dir = tempdir().unwrap();
        assert!(check_task_path_existence(dir.path(), "/etc/passwd").is_err());
        assert!(check_task_path_existence(dir.path(), "../outside.txt").is_err());
        assert!(check_task_path_existence(dir.path(), "docs/../../outside.txt").is_err());
    }

    #[cfg(unix)]
    #[test]
    fn check_task_path_existence_rejects_symlink_escape_for_existing_file() {
        let outside = tempdir().unwrap();
        fs::write(outside.path().join("secret.png"), b"x").unwrap();
        let ws = tempdir().unwrap();
        std::os::unix::fs::symlink(outside.path().join("secret.png"), ws.path().join("link.png")).unwrap();
        assert!(check_task_path_existence(ws.path(), "link.png").is_err());
    }

    #[cfg(unix)]
    #[test]
    fn check_task_path_existence_rejects_symlink_escape_for_missing_leaf() {
        // A symlinked directory INSIDE the worktree pointing OUTSIDE must
        // still fail containment even though the LEAF file itself doesn't
        // exist — the escaping symlink is the existing ancestor the walk-up
        // finds and canonicalizes.
        let outside = tempdir().unwrap();
        let ws = tempdir().unwrap();
        std::os::unix::fs::symlink(outside.path(), ws.path().join("escape")).unwrap();
        assert!(check_task_path_existence(ws.path(), "escape/missing.png").is_err());
    }

