    /// A monorepo whose SUBDIRECTORY is the project: one repo at the root,
    /// the project pointed at `packages/app`. Returns (repo root, project dir).
    fn monorepo_with_subdir_project() -> (tempfile::TempDir, PathBuf) {
        let dir = tempdir().unwrap();
        let root = dir.path().to_path_buf();
        git_run(&root, &["init", "-b", "main"]);
        let sub = root.join("packages/app/src");
        fs::create_dir_all(&sub).unwrap();
        fs::write(sub.join("index.js"), "one\ntwo\nthree\n").unwrap();
        fs::write(root.join("README.md"), "root\n").unwrap();
        git_run(&root, &["add", "-A"]);
        git_run(&root, &["-c", "user.name=Test", "-c", "user.email=t@t", "commit", "-m", "init"]);
        (dir, root.join("packages/app"))
    }

    /// GH: a project added as a SUBDIRECTORY of a monorepo showed every file
    /// as entirely deleted the moment you diffed it.
    ///
    /// git reports paths from `status --porcelain` relative to the REPOSITORY
    /// ROOT, whatever directory it ran in, while everything downstream in
    /// termic treats a path as relative to the TASK. For a project at
    /// `packages/app` the panel therefore listed `packages/app/src/index.js`,
    /// and the diff then looked for that under the project directory - i.e.
    /// `packages/app/packages/app/src/index.js`, which does not exist. The
    /// left side still resolved, because `git show HEAD:<path>` is
    /// root-relative too, so the pane got a full original against a missing
    /// modified and drew the whole file as removed.
    #[test]
    fn repo_prefix_answers_root_worktree_and_subdirectory() {
        let (_dir, project) = monorepo_with_subdir_project();
        let root = project.parent().unwrap().parent().unwrap().to_path_buf();
        assert_eq!(repo_prefix(&root), "");
        assert_eq!(repo_prefix(&project), "packages/app/");
        // A worktree's `.git` is a FILE, and it is still the root of its tree.
        // Its own tempdir: `git worktree add` refuses a path that exists, so a
        // shared parent would make this pass once and fail on every rerun.
        let wt_home = tempdir().unwrap();
        let wt = wt_home.path().join("wt");
        git_run(&root, &["worktree", "add", "-b", "side", &wt.to_string_lossy()]);
        assert!(wt.join(".git").is_file());
        assert_eq!(repo_prefix(&wt), "");
        // Not a repo at all: nothing to be relative to.
        let plain = tempdir().unwrap();
        assert_eq!(repo_prefix(plain.path()), "");
    }

    #[test]
    fn strip_repo_prefix_keeps_only_what_is_inside() {
        assert_eq!(strip_repo_prefix("", "src/a.rs"), Some("src/a.rs".into()));
        assert_eq!(strip_repo_prefix("packages/app/", "packages/app/src/a.rs"), Some("src/a.rs".into()));
        // Outside the project: no name for it here.
        assert_eq!(strip_repo_prefix("packages/app/", "README.md"), None);
        assert_eq!(strip_repo_prefix("packages/app/", "packages/other/a.rs"), None);
        // A sibling whose name merely STARTS with the project's is not inside
        // it - the trailing slash on the prefix is what rules that out.
        assert_eq!(strip_repo_prefix("packages/app/", "packages/app-utils/a.rs"), None);
        // The project directory itself is not a file in it.
        assert_eq!(strip_repo_prefix("packages/app/", "packages/app/"), None);
    }

    #[test]
    fn subdirectory_project_lists_paths_relative_to_the_project() {
        let (_dir, project) = monorepo_with_subdir_project();
        fs::write(project.join("src/index.js"), "one\ntwo CHANGED\nthree\n").unwrap();

        let repo = git_repo_status("app".into(), String::new(), "host", &project);

        let paths: Vec<&str> = repo.unstaged.iter().map(|f| f.path.as_str()).collect();
        assert_eq!(paths, vec!["src/index.js"], "paths must be relative to the project directory");
        // And the row's fingerprint must be a real one: it is what the
        // "viewed" mark anchors to, and a missing file gives an empty string.
        assert!(!repo.unstaged[0].fp.is_empty(), "fingerprint was resolved against the wrong directory");
    }

    #[test]
    fn subdirectory_project_diff_has_both_sides() {
        let (_dir, project) = monorepo_with_subdir_project();
        fs::write(project.join("src/index.js"), "one\ntwo CHANGED\nthree\n").unwrap();
        let task = Task { path: project.to_string_lossy().into_owned(), ..Default::default() };

        // Exactly the path the panel row above carries, straight into the diff:
        // the two have to speak one namespace or this is the deleted-file bug.
        let sides = task_file_diff_sides_for_task(&task, "src/index.js", None).unwrap();
        assert!(sides.original_exists);
        assert!(sides.modified_exists, "the working-tree side was looked for in the wrong directory");
        assert!(sides.original.contains("two\n"));
        assert!(sides.modified.contains("two CHANGED"));

        let patch = task_file_diff_for_task(&task, "src/index.js").unwrap();
        assert!(patch.contains("two CHANGED"), "patch: {patch}");
    }

    #[test]
    fn subdirectory_project_status_row_opens_the_diff_it_names() {
        // The bug end to end, in the one shape that produced it: the path the
        // panel row carries, handed straight to the diff the click opens. Both
        // halves can look right on their own and still not agree, and the
        // disagreement is the whole defect - the row said
        // `packages/app/src/index.js` and the diff went looking for that
        // UNDER `packages/app`.
        let (_dir, project) = monorepo_with_subdir_project();
        fs::write(project.join("src/index.js"), "one\ntwo CHANGED\nthree\n").unwrap();
        let task = Task { path: project.to_string_lossy().into_owned(), ..Default::default() };

        let repo = git_repo_status("app".into(), String::new(), "host", &project);
        let row = &repo.unstaged[0];
        let sides = task_file_diff_sides_for_task(&task, &row.path, None).unwrap();

        assert!(sides.original_exists && sides.modified_exists,
            "row {:?} did not open: original={} modified={}",
            row.path, sides.original_exists, sides.modified_exists);
        assert_eq!(sides.original, "one\ntwo\nthree\n");
        assert_eq!(sides.modified, "one\ntwo CHANGED\nthree\n");
    }

    #[test]
    fn a_subdirectory_projects_row_path_is_a_usable_pathspec() {
        // `task_stage` / `task_unstage` / `task_discard` hand the row's path
        // to git as a PATHSPEC, and git resolves a pathspec against the
        // directory it ran in - not against the repository root the row used
        // to be phrased in. Staging a row therefore looked for
        // `packages/app/packages/app/src/index.js` and quietly staged nothing.
        let (_dir, project) = monorepo_with_subdir_project();
        fs::write(project.join("src/index.js"), "one\ntwo CHANGED\nthree\n").unwrap();

        let row = git_repo_status("app".into(), String::new(), "host", &project)
            .unstaged[0].path.clone();
        // Exactly what task_stage runs, from exactly the directory it runs in.
        git_run(&project, &["add", "--", &row]);

        let after = git_repo_status("app".into(), String::new(), "host", &project);
        assert_eq!(after.staged.iter().map(|f| f.path.as_str()).collect::<Vec<_>>(), vec!["src/index.js"]);
        assert!(after.unstaged.is_empty());
    }

    #[test]
    fn subdirectory_project_scopes_status_to_the_project() {
        // A change OUTSIDE the project directory is not this project's
        // business: it cannot be diffed (there is no path for it in the
        // project's namespace), it cannot be opened, and staging it from here
        // would commit something the user never saw.
        let (_dir, project) = monorepo_with_subdir_project();
        let root = project.parent().unwrap().parent().unwrap().to_path_buf();
        fs::write(root.join("README.md"), "root changed\n").unwrap();
        fs::write(project.join("src/index.js"), "one\ntwo CHANGED\nthree\n").unwrap();

        let repo = git_repo_status("app".into(), String::new(), "host", &project);
        let paths: Vec<&str> = repo.unstaged.iter().map(|f| f.path.as_str()).collect();
        assert_eq!(paths, vec!["src/index.js"]);
        assert_eq!(repo.changed, 1);
    }

    #[test]
    fn subdirectory_project_handles_untracked_staged_and_renamed() {
        let (_dir, project) = monorepo_with_subdir_project();
        let root = project.parent().unwrap().parent().unwrap().to_path_buf();
        fs::write(project.join("src/untracked.js"), "new\n").unwrap();
        fs::write(project.join("src/staged.js"), "staged\n").unwrap();
        git_run(&root, &["add", "packages/app/src/staged.js"]);
        git_run(&root, &["mv", "packages/app/src/index.js", "packages/app/src/renamed.js"]);

        let repo = git_repo_status("app".into(), String::new(), "host", &project);
        let mut staged: Vec<&str> = repo.staged.iter().map(|f| f.path.as_str()).collect();
        let mut unstaged: Vec<&str> = repo.unstaged.iter().map(|f| f.path.as_str()).collect();
        staged.sort();
        unstaged.sort();
        // A rename keeps its NEW path, which is the one on disk and the one
        // `git add` expects - relative to the project like every other row.
        assert_eq!(staged, vec!["src/renamed.js", "src/staged.js"]);
        assert_eq!(unstaged, vec!["src/untracked.js"]);
    }

    #[test]
    fn a_repo_root_project_is_untouched_by_the_subdirectory_handling() {
        // The 99% case: nothing about a project that IS its repo root may
        // change, prefix logic included.
        let dir = tempdir().unwrap();
        git_init_with_commit(dir.path());
        fs::write(dir.path().join("base.txt"), "changed\n").unwrap();

        let repo = git_repo_status("r".into(), String::new(), "host", dir.path());
        let paths: Vec<&str> = repo.unstaged.iter().map(|f| f.path.as_str()).collect();
        assert_eq!(paths, vec!["base.txt"]);

        let task = Task { path: dir.path().to_string_lossy().into_owned(), ..Default::default() };
        let sides = task_file_diff_sides_for_task(&task, "base.txt", None).unwrap();
        assert!(sides.original_exists && sides.modified_exists);
        assert!(sides.modified.contains("changed"));
    }

    #[test]
    fn diff_sides_scope_splits_staged_and_unstaged() {
        // GH #122: a file staged and then edited again must show
        // index→worktree from the Unstaged row and HEAD→index from the
        // Staged row — not the full uncommitted diff from both.
        let dir = tempdir().unwrap();
        git_init_with_commit(dir.path());
        let run = |args: &[&str]| {
            let out = std::process::Command::new("git").args(args).current_dir(dir.path()).output().unwrap();
            assert!(out.status.success(), "git {:?} failed: {}", args, String::from_utf8_lossy(&out.stderr));
        };
        fs::write(dir.path().join("base.txt"), "staged content\n").unwrap();
        run(&["add", "base.txt"]);
        fs::write(dir.path().join("base.txt"), "worktree content\n").unwrap();

        let task = Task {
            path: dir.path().to_string_lossy().into_owned(),
            ..Default::default()
        };

        let full = task_file_diff_sides_for_task(&task, "base.txt", None).unwrap();
        assert_eq!(full.original, "base content\n");
        assert_eq!(full.modified, "worktree content\n");

        let staged = task_file_diff_sides_for_task(&task, "base.txt", Some("staged")).unwrap();
        assert_eq!(staged.original, "base content\n");
        assert_eq!(staged.modified, "staged content\n");

        let unstaged = task_file_diff_sides_for_task(&task, "base.txt", Some("unstaged")).unwrap();
        assert_eq!(unstaged.original, "staged content\n");
        assert_eq!(unstaged.modified, "worktree content\n");

        assert_eq!(full.kind, "text");
        assert_eq!(full.original_bytes, "base content\n".len() as u64);
    }

    /// A 1×1 transparent PNG — real enough that an <img> renders it.
    const TINY_PNG: &[u8] = &[
        0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0x00, 0x00, 0x00, 0x0d, 0x49, 0x48, 0x44, 0x52,
        0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x08, 0x06, 0x00, 0x00, 0x00, 0x1f, 0x15, 0xc4,
        0x89, 0x00, 0x00, 0x00, 0x0a, 0x49, 0x44, 0x41, 0x54, 0x78, 0x9c, 0x63, 0x00, 0x01, 0x00, 0x00,
        0x05, 0x00, 0x01, 0x0d, 0x0a, 0x2d, 0xb4, 0x00, 0x00, 0x00, 0x00, 0x49, 0x45, 0x4e, 0x44, 0xae,
        0x42, 0x60, 0x82,
    ];

    /// `git_commit_file` takes a &str, so binary fixtures commit their bytes
    /// here instead.
    fn git_commit_bytes(repo: &Path, name: &str, bytes: &[u8]) {
        fs::write(repo.join(name), bytes).unwrap();
        git_run(repo, &["add", "."]);
        git_run(repo, &["-c", "user.name=Test", "-c", "user.email=t@t", "commit", "-m", name]);
    }

    fn task_at(dir: &Path) -> Task {
        Task { path: dir.to_string_lossy().into_owned(), ..Default::default() }
    }

    #[test]
    fn diff_sides_ships_both_png_sides_as_base64() {
        use base64::Engine as _;
        let dir = tempdir().unwrap();
        git_init_with_commit(dir.path());
        git_commit_bytes(dir.path(), "shot.png", TINY_PNG);
        // Any different bytes; the modified side just has to not equal HEAD.
        let edited: Vec<u8> = TINY_PNG.iter().copied().chain([0u8, 1, 2]).collect();
        fs::write(dir.path().join("shot.png"), &edited).unwrap();

        let sides = task_file_diff_sides_for_task(&task_at(dir.path()), "shot.png", None).unwrap();
        assert_eq!(sides.kind, "image");
        assert_eq!(sides.mime.as_deref(), Some("image/png"));
        assert!(sides.original_exists && sides.modified_exists);
        // The whole point: bytes survive the round trip instead of being
        // lossily decoded into U+FFFD.
        let dec = |s: &Option<String>| {
            base64::engine::general_purpose::STANDARD.decode(s.as_ref().unwrap()).unwrap()
        };
        assert_eq!(dec(&sides.original_data), TINY_PNG);
        assert_eq!(dec(&sides.modified_data), edited);
        assert_eq!(sides.original_bytes, TINY_PNG.len() as u64);
        assert_eq!(sides.modified_bytes, edited.len() as u64);
        // Text fields stay empty for a non-text diff.
        assert!(sides.original.is_empty() && sides.modified.is_empty());
        assert!(!sides.fp.is_empty());
    }

    #[test]
    fn diff_sides_reports_an_untracked_png_as_a_one_sided_image() {
        let dir = tempdir().unwrap();
        git_init_with_commit(dir.path());
        fs::write(dir.path().join("new.png"), TINY_PNG).unwrap();

        let sides = task_file_diff_sides_for_task(&task_at(dir.path()), "new.png", None).unwrap();
        assert_eq!(sides.kind, "image");
        assert!(!sides.original_exists);
        assert!(sides.modified_exists);
        assert!(sides.original_data.is_none());
        assert!(sides.modified_data.is_some());
        assert_eq!(sides.original_bytes, 0);
        assert_eq!(sides.modified_bytes, TINY_PNG.len() as u64);
    }

    #[test]
    fn diff_sides_reports_a_deleted_png_as_a_one_sided_image() {
        // The delete half of add/delete symmetry: the worktree file is gone,
        // so `safe_task_path` can't canonicalize it and the image probe has
        // to come off the path's extension alone. That failing used to drop
        // this to "binary", and the pane showed "Binary file · deleted"
        // instead of the picture that was removed.
        let dir = tempdir().unwrap();
        git_init_with_commit(dir.path());
        git_commit_bytes(dir.path(), "gone.png", TINY_PNG);
        fs::remove_file(dir.path().join("gone.png")).unwrap();

        let sides = task_file_diff_sides_for_task(&task_at(dir.path()), "gone.png", None).unwrap();
        assert_eq!(sides.kind, "image");
        assert_eq!(sides.mime.as_deref(), Some("image/png"));
        assert!(sides.original_exists);
        assert!(!sides.modified_exists);
        assert!(sides.original_data.is_some());
        assert!(sides.modified_data.is_none());
        assert_eq!(sides.original_bytes, TINY_PNG.len() as u64);
        assert_eq!(sides.modified_bytes, 0);
        // No worktree file → no fingerprint; the pane hides "Viewed" on "".
        assert!(sides.fp.is_empty());
    }

    #[test]
    fn diff_sides_reports_a_commit_scope_deleted_png_as_a_one_sided_image() {
        // A History diff whose right side is a blob, not the worktree: the
        // deletion case must not depend on the file's on-disk state at all.
        let dir = tempdir().unwrap();
        git_init_with_commit(dir.path());
        git_set_identity(dir.path());
        git_commit_bytes(dir.path(), "gone.png", TINY_PNG);
        fs::remove_file(dir.path().join("gone.png")).unwrap();
        git_run(dir.path(), &["add", "-A"]);
        git_run(dir.path(), &["commit", "-m", "drop gone.png"]);
        let sha = git_head(dir.path());
        // Recreate the file so the worktree copy exists but is irrelevant:
        // `commit:` reads both sides from the object store either way.
        fs::write(dir.path().join("gone.png"), TINY_PNG).unwrap();

        let sides = task_file_diff_sides_for_task(
            &task_at(dir.path()),
            "gone.png",
            Some(&format!("commit:{sha}")),
        )
        .unwrap();
        assert_eq!(sides.kind, "image");
        assert!(sides.original_exists);
        assert!(!sides.modified_exists);
        assert!(sides.original_data.is_some());
        assert!(sides.modified_data.is_none());
    }

    #[test]
    fn diff_sides_summarizes_a_non_image_binary_without_shipping_bytes() {
        let dir = tempdir().unwrap();
        git_init_with_commit(dir.path());
        git_commit_bytes(dir.path(), "blob.bin", &[0u8, 159, 146, 150]);
        fs::write(dir.path().join("blob.bin"), [0u8, 1, 2, 3, 4, 5]).unwrap();

        let sides = task_file_diff_sides_for_task(&task_at(dir.path()), "blob.bin", None).unwrap();
        assert_eq!(sides.kind, "binary");
        assert!(sides.mime.is_none());
        assert!(sides.original_data.is_none() && sides.modified_data.is_none());
        assert_eq!(sides.original_bytes, 4);
        assert_eq!(sides.modified_bytes, 6);
    }

    #[test]
    fn diff_sides_keeps_svg_as_a_text_diff() {
        // SVG is in the image extension whitelist but is valid UTF-8, and a
        // line diff of the changed attribute beats two pictures.
        let dir = tempdir().unwrap();
        git_init_with_commit(dir.path());
        git_commit_bytes(dir.path(), "icon.svg", b"<svg width=\"1\"/>\n");
        fs::write(dir.path().join("icon.svg"), "<svg width=\"2\"/>\n").unwrap();

        let sides = task_file_diff_sides_for_task(&task_at(dir.path()), "icon.svg", None).unwrap();
        assert_eq!(sides.kind, "text");
        assert_eq!(sides.original, "<svg width=\"1\"/>\n");
        assert_eq!(sides.modified, "<svg width=\"2\"/>\n");
        assert!(sides.original_data.is_none() && sides.modified_data.is_none());
    }

    // ──────────────── spotlight git mechanics ────────────────

    /// Initialize a bare git repo at `path` with one commit so HEAD and
    /// base branch exist. Returns the committed file path.
    fn git_init_with_commit(path: &Path) -> PathBuf {
        let run = |args: &[&str]| {
            let out = std::process::Command::new("git").args(args).current_dir(path).output().unwrap();
            assert!(out.status.success(), "git {:?} failed: {}", args, String::from_utf8_lossy(&out.stderr));
        };
        run(&["init", "-b", "main"]);
        run(&["-c", "user.name=Test", "-c", "user.email=t@t", "commit", "--allow-empty", "-m", "init"]);
        let f = path.join("base.txt");
        fs::write(&f, "base content\n").unwrap();
        run(&["add", "."]);
        run(&["-c", "user.name=Test", "-c", "user.email=t@t", "commit", "-m", "base"]);
        f
    }

    /// Add a real git worktree of `repo` at `wt` on a new branch `branch`.
    /// Worktrees share the object DB — exactly what spotlight's detached
    /// checkout relies on. Returns nothing; `wt` is checked out on `branch`.
    fn git_worktree_add(repo: &Path, wt: &Path, branch: &str) {
        let out = std::process::Command::new("git")
            .args(["worktree", "add", &wt.to_string_lossy(), "-b", branch])
            .current_dir(repo)
            .output().unwrap();
        assert!(out.status.success(), "worktree add failed: {}", String::from_utf8_lossy(&out.stderr));
    }

    fn git_head(repo: &Path) -> String {
        String::from_utf8_lossy(
            &std::process::Command::new("git")
                .args(["rev-parse", "HEAD"])
                .current_dir(repo)
                .output().unwrap().stdout,
        ).trim().to_string()
    }

    /// Resolve a ref (e.g. a branch name) to a SHA in `repo`.
    fn git_rev(repo: &Path, refname: &str) -> String {
        String::from_utf8_lossy(
            &std::process::Command::new("git")
                .args(["rev-parse", refname])
                .current_dir(repo)
                .output().unwrap().stdout,
        ).trim().to_string()
    }

    // diff_base_ref: the diff has to resolve the stored base the same way task
    // create does. A repo with no remote is still pinned to "origin/main"
    // (detect_default_remote falls back to the name "origin" whether or not
    // that remote exists), so passing the stored value through raw made every
    // git call fail, and the failures were folded into "no changes".
    #[test]
    fn diff_base_ref_resolves_a_remote_tracking_base_in_a_local_only_repo() {
        let dir = tempdir().unwrap();
        let repo = dir.path();
        git_init_with_commit(repo); // local-only: branch "main", no origin.

        assert!(git(&["--no-pager", "diff", "origin/main"], repo).is_err(),
                "the stored base must be unusable here, or this proves nothing");
        assert_eq!(diff_base_ref(repo, "origin/main").as_deref(), Some("main"));
    }

    // No commits means no HEAD, so even resolve_base_ref's fallback lands on a
    // ref that does not exist. There is nothing to diff against, which is not
    // the same as a failure: the untracked scan still has files to report.
    // Same for an orphan HEAD, where the base resolves and HEAD does not.
    #[test]
    fn diff_base_ref_is_none_in_a_repo_with_no_commits() {
        let dir = tempdir().unwrap();
        let repo = dir.path();
        let out = std::process::Command::new("git")
            .args(["init", "-b", "main"]).current_dir(repo).output().unwrap();
        assert!(out.status.success());

        assert_eq!(diff_base_ref(repo, "origin/main"), None);
    }

    #[test]
    fn diff_base_ref_is_none_on_an_orphan_head() {
        let dir = tempdir().unwrap();
        let repo = dir.path();
        git_init_with_commit(repo);
        let out = std::process::Command::new("git")
            .args(["checkout", "--orphan", "fresh"]).current_dir(repo).output().unwrap();
        assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));

        // The base resolves here; HEAD is what does not, and `git log
        // main..HEAD` would fail on it.
        assert_eq!(resolve_base_ref(repo, "origin/main"), "main");
        assert_eq!(diff_base_ref(repo, "origin/main"), None);
    }

    // resolve_base_ref: a worktree branch must be cut from a ref that EXISTS.
    // The project default base is remote-tracking ("origin/main"), which a
    // local-only repo (no remote) doesn't have — the reason a race/New Task
    // errored with "not a valid object name: origin/main". Verify the fallback.
    #[test]
    fn a_bare_name_that_only_exists_on_the_remote_still_resolves() {
        // Row three of the report, and the common case rather than an edge
        // one: `gh pr view <n> --json headRefName` returns a BARE branch name,
        // and for any branch outside `remote.origin.fetch` that name exists
        // only as `refs/remotes/origin/<name>`. `git checkout <name>` DWIMs
        // it; `git rev-parse --verify <name>` does not, so resolution built on
        // rev-parse rejected a name users reasonably expect to work, and the
        // rejection was then swallowed into a fallback.
        let dir = tempdir().unwrap();
        let origin = dir.path().join("origin.git");
        let work = dir.path().join("work");
        fs::create_dir_all(&origin).unwrap();
        fs::create_dir_all(&work).unwrap();
        let run = |cwd: &Path, args: &[&str]| {
            let out = std::process::Command::new("git")
                .args(args).current_dir(cwd)
                .env("GIT_AUTHOR_NAME", "T").env("GIT_AUTHOR_EMAIL", "t@t")
                .env("GIT_COMMITTER_NAME", "T").env("GIT_COMMITTER_EMAIL", "t@t")
                .output().unwrap();
            assert!(out.status.success(), "git {:?}: {}", args, String::from_utf8_lossy(&out.stderr));
        };
        run(&origin, &["init", "--bare", "-b", "main"]);
        git_init_with_commit(&work);
        run(&work, &["remote", "add", "origin", &origin.to_string_lossy()]);
        run(&work, &["push", "-u", "origin", "main"]);
        // A branch that exists ONLY on the remote, with its own commit.
        run(&work, &["checkout", "-b", "feature/pr-1"]);
        run(&work, &["commit", "--allow-empty", "-m", "pr work"]);
        run(&work, &["push", "origin", "feature/pr-1"]);
        let pr_sha = std::process::Command::new("git")
            .args(["rev-parse", "HEAD"]).current_dir(&work).output().unwrap();
        let pr_sha = String::from_utf8_lossy(&pr_sha.stdout).trim().to_string();
        // Delete the local branch: now the name lives only under refs/remotes.
        run(&work, &["checkout", "main"]);
        run(&work, &["branch", "-D", "feature/pr-1"]);

        let got = try_resolve_base_ref(&work, "feature/pr-1")
            .expect("a bare name present only on the remote must resolve");
        let got_sha = std::process::Command::new("git")
            .args(["rev-parse", &got]).current_dir(&work).output().unwrap();
        assert_eq!(String::from_utf8_lossy(&got_sha.stdout).trim(), pr_sha,
            "it must resolve to the REMOTE branch's commit, not to something \
             that merely exists: a test asserting only Some(_) passes on a \
             fallback to HEAD");
    }

    #[test]
    fn an_unresolvable_base_resolves_to_NOTHING_rather_than_to_head() {
        // The swallowed failure is the bug, not the ref syntax. `resolve_base_ref`
        // still answers HEAD, because a STORED base legitimately falls back
        // (a local-only repo pinned to origin/main). The strict variant is what
        // a user-supplied `--base` goes through, and it must say no.
        let dir = tempdir().unwrap();
        let repo = dir.path();
        git_init_with_commit(repo);
        assert_eq!(try_resolve_base_ref(repo, "this-ref-does-not-exist"), None);
        assert_eq!(try_resolve_base_ref(repo, "origin/nope"), None);
        // ...and the tolerant wrapper keeps its fallback, so nothing that
        // depends on it changes behaviour.
        assert_eq!(resolve_base_ref(repo, "this-ref-does-not-exist"), "HEAD");
    }

    // ──────────────── checkout_existing_branch ────────────────

    /// A bare `origin`, a `colleague` repo that pushes to it, and a `work`
    /// clone taken after the colleague pushed `alice/fix`. So `work` has
    /// `refs/remotes/origin/alice/fix` and no local `alice/fix`: the shape of
    /// "review someone else's branch". Returns (tempdir, work, colleague).
    fn checkout_fixture() -> (tempfile::TempDir, PathBuf, PathBuf) {
        let dir = tempdir().unwrap();
        let origin = dir.path().join("origin.git");
        let colleague = dir.path().join("colleague");
        let work = dir.path().join("work");
        fs::create_dir_all(&origin).unwrap();
        fs::create_dir_all(&colleague).unwrap();
        git_run(&origin, &["init", "--bare", "-b", "main"]);
        git_init_with_commit(&colleague);
        git_set_identity(&colleague);
        git_run(&colleague, &["remote", "add", "origin", &origin.to_string_lossy()]);
        git_run(&colleague, &["push", "origin", "main"]);
        git_run(&colleague, &["checkout", "-b", "alice/fix"]);
        git_commit_file(&colleague, "fix.txt", "the fix\n", "fix");
        git_run(&colleague, &["push", "origin", "alice/fix"]);
        git_run(dir.path(), &["clone", "-q", &origin.to_string_lossy(), &work.to_string_lossy()]);
        git_set_identity(&work);
        (dir, work, colleague)
    }

    fn local_branches(repo: &Path) -> String {
        git(&["for-each-ref", "--format=%(refname) %(objectname)", "refs/heads"], repo).unwrap()
    }

    #[test]
    fn checkout_uses_a_local_branch_as_it_is() {
        let (_dir, work, _colleague) = checkout_fixture();
        git_run(&work, &["branch", "mine"]);
        let before = local_branches(&work);
        let got = checkout_existing_branch(&work, "mine", true, &mut |_| {}).unwrap();
        assert_eq!(got, "mine");
        assert_eq!(local_branches(&work), before, "a local branch must not be recreated or moved");
    }

    #[test]
    fn checkout_tracks_a_branch_that_only_exists_on_the_remote() {
        // Both spellings a user reaches for: the bare name the colleague said,
        // and the `origin/...` ref the picker lists.
        for requested in ["alice/fix", "origin/alice/fix"] {
            let (_dir, work, colleague) = checkout_fixture();
            let mut lines = Vec::new();
            let got = checkout_existing_branch(&work, requested, false, &mut |l| lines.push(l)).unwrap();
            assert_eq!(got, "alice/fix", "{requested}");
            assert_eq!(
                git_rev(&work, "refs/heads/alice/fix"),
                git_rev(&colleague, "alice/fix"),
                "{requested}: the local branch must sit on the COLLEAGUE's commit, not on main",
            );
            assert_eq!(
                git(&["rev-parse", "--abbrev-ref", "alice/fix@{upstream}"], &work).unwrap().trim(),
                "origin/alice/fix",
                "{requested}: push and pull on it have to reach their branch",
            );
            assert!(lines.iter().any(|l| l.contains("tracking 'origin/alice/fix'")), "{lines:?}");
        }
    }

    #[test]
    fn checkout_fetches_a_branch_pushed_after_the_last_fetch() {
        let (_dir, work, colleague) = checkout_fixture();
        git_run(&colleague, &["checkout", "-b", "bob/late"]);
        git_commit_file(&colleague, "late.txt", "late\n", "late");
        git_run(&colleague, &["push", "origin", "bob/late"]);

        // Without the fetch, this repo has never heard of it.
        assert!(checkout_existing_branch(&work, "bob/late", false, &mut |_| {}).is_err());
        assert!(git(&["rev-parse", "--verify", "--quiet", "refs/heads/bob/late"], &work).is_err());

        let got = checkout_existing_branch(&work, "bob/late", true, &mut |_| {}).unwrap();
        assert_eq!(got, "bob/late");
        assert_eq!(git_rev(&work, "refs/heads/bob/late"), git_rev(&colleague, "bob/late"));
    }

    #[test]
    fn checkout_of_an_unknown_branch_is_an_error_and_creates_nothing() {
        // The bug this exists for: the new-branch path turns an unknown name
        // into a fresh branch off the base, and an agent then reviews main
        // under the colleague's branch name.
        let (_dir, work, _colleague) = checkout_fixture();
        let before = local_branches(&work);
        let err = checkout_existing_branch(&work, "nobody/has-this", true, &mut |_| {}).unwrap_err();
        assert!(err.contains("no branch 'nobody/has-this'") && err.contains("origin"), "{err}");
        assert_eq!(local_branches(&work), before, "a refused checkout must leave no branch behind");
    }

    #[test]
    fn checkout_in_a_repo_with_no_remote_is_a_clean_error() {
        // detect_default_remote answers "origin" even when there is none, and
        // fetch_ref no-ops for it, so this has to fall through to the error.
        let dir = tempdir().unwrap();
        let repo = dir.path();
        git_init_with_commit(repo);
        let err = checkout_existing_branch(repo, "feature/x", true, &mut |_| {}).unwrap_err();
        assert!(err.contains("no branch 'feature/x'"), "{err}");
        git_run(repo, &["branch", "feature/x"]);
        assert_eq!(checkout_existing_branch(repo, "feature/x", true, &mut |_| {}).unwrap(), "feature/x");
    }

    #[test]
    fn checkout_refuses_names_git_would_read_as_options_or_reject() {
        let (_dir, work, _colleague) = checkout_fixture();
        assert!(checkout_existing_branch(&work, "  ", true, &mut |_| {}).unwrap_err().contains("name the branch"));
        for bad in ["--upload-pack=touch pwned", "-x", "origin/-x", "a..b", "has space", "ends.lock"] {
            let err = checkout_existing_branch(&work, bad, true, &mut |_| {}).unwrap_err();
            assert!(err.contains("not a valid branch name"), "{bad}: {err}");
        }
    }

    #[test]
    fn checkout_prefers_the_local_branch_over_a_diverged_remote_one() {
        // The local copy may hold the user's own review commits: checking the
        // branch out again must not move it to wherever the remote went.
        let (_dir, work, colleague) = checkout_fixture();
        git_run(&work, &["checkout", "-q", "alice/fix"]);
        git_commit_file(&work, "mine.txt", "mine\n", "my note");
        git_run(&work, &["checkout", "-q", "main"]);
        let mine = git_rev(&work, "refs/heads/alice/fix");
        git_run(&colleague, &["checkout", "-q", "alice/fix"]);
        git_commit_file(&colleague, "more.txt", "more\n", "more");
        git_run(&colleague, &["push", "origin", "alice/fix"]);

        let got = checkout_existing_branch(&work, "origin/alice/fix", true, &mut |_| {}).unwrap();
        assert_eq!(got, "alice/fix");
        assert_eq!(git_rev(&work, "refs/heads/alice/fix"), mine);
        assert_ne!(git_rev(&work, "refs/remotes/origin/alice/fix"), mine, "the fetch did move the remote ref");
    }

    // ensure_restore_branch: "Delete the branch when archiving" removed the
    // local branch, and restore has to put the worktree back on the RIGHT one.

    fn archived_task(branch: &str, checkout_existing: bool) -> Task {
        Task {
            branch: branch.into(),
            base_branch: "origin/main".into(),
            checkout_existing,
            ..Default::default()
        }
    }

    #[test]
    fn restore_brings_a_deleted_checkout_branch_back_from_the_remote() {
        let (_dir, work, colleague) = checkout_fixture();
        // Create checked it out, archive deleted the local copy.
        checkout_existing_branch(&work, "alice/fix", false, &mut |_| {}).unwrap();
        git_run(&work, &["branch", "-D", "alice/fix"]);

        ensure_restore_branch(&work, &archived_task("alice/fix", true), true).unwrap();
        assert_eq!(
            git_rev(&work, "refs/heads/alice/fix"),
            git_rev(&colleague, "alice/fix"),
            "the colleague's commit, not main under their branch's name",
        );
        assert_ne!(git_rev(&work, "refs/heads/alice/fix"), git_rev(&work, "main"));
        assert_eq!(
            git(&["rev-parse", "--abbrev-ref", "alice/fix@{upstream}"], &work).unwrap().trim(),
            "origin/alice/fix",
        );
    }

    #[test]
    fn restore_still_cuts_a_tasks_own_deleted_branch_from_its_base() {
        // The flag is what separates the two: an ordinary task's branch was
        // cut from the base in the first place, so that is where it goes back.
        let (_dir, work, _colleague) = checkout_fixture();
        ensure_restore_branch(&work, &archived_task("feature/mine", false), true).unwrap();
        assert_eq!(git_rev(&work, "refs/heads/feature/mine"), git_rev(&work, "origin/main"));
        // Even when the name also exists on the remote: without the flag it
        // is not someone else's branch.
        ensure_restore_branch(&work, &archived_task("alice/fix", false), true).unwrap();
        assert_eq!(git_rev(&work, "refs/heads/alice/fix"), git_rev(&work, "origin/main"));
    }

    #[test]
    fn restore_fails_a_checkout_whose_branch_is_gone_everywhere() {
        // Gone locally AND on the remote: an error, never main in its place.
        let (_dir, work, colleague) = checkout_fixture();
        git_run(&colleague, &["push", "origin", "--delete", "alice/fix"]);
        git_run(&work, &["fetch", "-q", "--prune", "origin"]);
        let before = local_branches(&work);
        let err = ensure_restore_branch(&work, &archived_task("alice/fix", true), true).unwrap_err();
        assert!(err.contains("restore branch 'alice/fix'") && err.contains("no branch"), "{err}");
        assert_eq!(local_branches(&work), before);
    }

    #[test]
    fn restore_leaves_a_branch_that_still_exists_alone() {
        let (_dir, work, _colleague) = checkout_fixture();
        git_run(&work, &["branch", "kept"]);
        let before = local_branches(&work);
        ensure_restore_branch(&work, &archived_task("kept", true), true).unwrap();
        ensure_restore_branch(&work, &archived_task("kept", false), true).unwrap();
        assert_eq!(local_branches(&work), before);
    }

    #[test]
    fn a_ref_that_is_not_a_commit_is_refused_here_rather_than_by_git_branch() {
        let dir = tempdir().unwrap();
        let repo = dir.path();
        git_init_with_commit(repo);
        // A tree-ish that exists and is not a commit. `git branch` would fail
        // on it anyway; failing here keeps the error about the ref the user
        // typed instead of about git plumbing.
        assert_eq!(try_resolve_base_ref(repo, "HEAD^{tree}"), None);
    }

    #[test]
    fn resolve_base_ref_falls_back_when_no_remote() {
        let dir = tempdir().unwrap();
        let repo = dir.path();
        git_init_with_commit(repo); // local-only: branch "main", no origin.

        // The default base doesn't resolve here → fall back to the local branch.
        assert_eq!(resolve_base_ref(repo, "origin/main"), "main");
        // A multi-segment remote ref strips only the remote: origin/feature/x.
        // No such local branch → HEAD (create still succeeds off current tip).
        assert_eq!(resolve_base_ref(repo, "origin/feature/x"), "HEAD");
        // A base that already exists is returned unchanged (the has-remote path
        // and any explicit local base): no surprise rewrites.
        assert_eq!(resolve_base_ref(repo, "main"), "main");
        // A totally unknown local ref still resolves to something creatable.
        assert_eq!(resolve_base_ref(repo, "nope"), "HEAD");
    }

    // With a real origin/main present, resolve_base_ref must PREFER it (the
    // remote-tracking cut), not silently drop to local — else GH #79 (cut from
    // latest fetched remote) regresses for every normal cloned repo.
    #[test]
    fn resolve_base_ref_prefers_existing_remote_ref() {
        let dir = tempdir().unwrap();
        let origin = dir.path().join("origin.git");
        let clone = dir.path().join("clone");
        let run = |args: &[&str], cwd: &Path| {
            let out = std::process::Command::new("git")
                .args(args).current_dir(cwd).output().unwrap();
            assert!(out.status.success(), "git {:?}: {}", args, String::from_utf8_lossy(&out.stderr));
        };
        let work = git_init_with_commit(dir.path()); // seed a commit in dir root
        let _ = work;
        run(&["init", "--bare", &origin.to_string_lossy()], dir.path());
        run(&["remote", "add", "origin", &origin.to_string_lossy()], dir.path());
        run(&["push", "origin", "main"], dir.path());
        run(&["clone", &origin.to_string_lossy(), &clone.to_string_lossy()], dir.path());

        // In the clone, origin/main is a real ref → returned as-is.
        assert_eq!(resolve_base_ref(&clone, "origin/main"), "origin/main");
    }

    // task_base_branch: an explicit per-task base wins, otherwise the branch
    // pinned on the project. No repo access, no HEAD reading — the pin IS the
    // answer, which is the whole point of collapsing the old two-mode design.
    #[test]
    fn task_base_branch_precedence() {
        // Nothing pinned per task → the project's pin.
        assert_eq!(task_base_branch("origin/main", None), "origin/main");
        // An explicit base (New Task dialog / CLI `base`) outranks the pin.
        assert_eq!(task_base_branch("origin/main", Some("release/1.x")), "release/1.x");
        // Blank/whitespace counts as ABSENT. `unwrap_or_else` alone let
        // Some("") through, and an empty base resolves to HEAD in
        // resolve_base_ref — a silent cut from wherever the repo was sitting.
        assert_eq!(task_base_branch("origin/main", Some("")), "origin/main");
        assert_eq!(task_base_branch("origin/main", Some("   ")), "origin/main");
        // A padded real value is trimmed, not rejected.
        assert_eq!(task_base_branch("origin/main", Some(" dev ")), "dev");
    }

    // current_branch still backs the "· current" hint in the picker, so it has
    // to keep tracking HEAD even though nothing branches off it automatically.
    #[test]
    fn current_branch_tracks_head() {
        let dir = tempdir().unwrap();
        let repo = dir.path();
        git_init_with_commit(repo);
        assert_eq!(current_branch(repo).as_deref(), Some("main"));

        let out = std::process::Command::new("git")
            .args(["checkout", "-q", "-b", "dev"]).current_dir(repo).output().unwrap();
        assert!(out.status.success());
        assert_eq!(current_branch(repo).as_deref(), Some("dev"));

        // Detached HEAD has no branch to name; the hint just goes away.
        let head = git_head(repo);
        std::process::Command::new("git")
            .args(["checkout", "-q", "--detach", &head]).current_dir(repo).output().unwrap();
        assert_eq!(current_branch(repo), None);
    }

    // A non-repo path must not panic or return a bogus branch — project
    // root_path can point at a plain folder (non-git projects, issue #4).
    #[test]
    fn current_branch_none_outside_a_repo() {
        let dir = tempdir().unwrap();
        assert_eq!(current_branch(dir.path()), None);
    }

    /// Current branch name, or empty when in detached HEAD.
    fn git_branch(repo: &Path) -> String {
        String::from_utf8_lossy(
            &std::process::Command::new("git")
                .args(["symbolic-ref", "--quiet", "--short", "HEAD"])
                .current_dir(repo)
                .output().unwrap().stdout,
        ).trim().to_string()
    }

    fn git_is_clean(repo: &Path) -> bool {
        let out = std::process::Command::new("git")
            .args(["status", "--porcelain"])
            .current_dir(repo)
            .output().unwrap();
        String::from_utf8_lossy(&out.stdout).trim().is_empty()
    }

    // ──────────────── git_update_repo (issue #101) ────────────────

    /// Pin a committer identity in the repo's own config. `git_init_with_commit`
    /// passes `-c user.*` per command, leaving the repo itself identity-less, so
    /// a merge or rebase commit here would otherwise depend on the machine's
    /// global git config. Worktrees share this config.
    fn git_set_identity(repo: &Path) {
        for args in [["config", "user.name", "Test"], ["config", "user.email", "t@t"]] {
            let out = std::process::Command::new("git").args(args).current_dir(repo).output().unwrap();
            assert!(out.status.success(), "git {args:?} failed");
        }
    }

    fn git_run(repo: &Path, args: &[&str]) {
        let out = std::process::Command::new("git").args(args).current_dir(repo).output().unwrap();
        assert!(out.status.success(), "git {:?} failed: {}", args, String::from_utf8_lossy(&out.stderr));
    }

    /// Write `name` with `content` in `repo` and commit it.
    fn git_commit_file(repo: &Path, name: &str, content: &str, msg: &str) {
        fs::write(repo.join(name), content).unwrap();
        git_run(repo, &["add", "."]);
        git_run(repo, &["commit", "-m", msg]);
    }

    /// A main repo (identity pinned, one commit) plus a worktree on `task`.
    /// Returns the two tempdirs (kept alive by the caller) and their paths.
    fn update_fixture() -> (tempfile::TempDir, tempfile::TempDir, PathBuf, PathBuf) {
        let main_dir = tempdir().unwrap();
        let wt_dir = tempdir().unwrap();
        let main = main_dir.path().to_path_buf();
        git_init_with_commit(&main);
        git_set_identity(&main);
        let wt = wt_dir.path().join("wt");
        git_worktree_add(&main, &wt, "task");
        (main_dir, wt_dir, main, wt)
    }

    #[test]
    fn archive_reaches_a_shell_that_only_its_owner_ties_to_the_task() {
        let owner = |t: &str| PtyOwner { task_id: Some(t.into()), tab_id: None, kind: "shell".into() };
        // A main-panel shell: no task_id, no role, only the owner.
        assert!(is_untagged_task_pty(None, None, Some(&owner("t1")), "t1"));
        assert!(!is_untagged_task_pty(None, None, Some(&owner("t2")), "t1"));
        // An agent carries task_id and is stop_task_ptys's, not this one's.
        assert!(!is_untagged_task_pty(Some("t1"), None, Some(&owner("t1")), "t1"));
        // Nothing naming the task.
        assert!(!is_untagged_task_pty(None, None, None, "t1"));
    }

    #[test]
    fn a_repo_git_will_not_open_says_why_instead_of_not_a_repo() {
        let dir = tempdir().unwrap();
        // No .git: not a repo, the caller's own message stands.
        assert_eq!(git_open_error(dir.path(), "x", "fatal: not a git repository"), None);
        // Git's ownership check names the command that trusts it.
        let dubious = "git [\"rev-parse\"] failed: fatal: detected dubious ownership in repository at 'C:/Projects/seat-be'";
        let msg = git_open_error(Path::new(r"C:\Projects\seat-be"), r"C:\Projects\seat-be", dubious).unwrap();
        assert!(msg.contains("owned by another user account"), "{msg}");
        assert!(msg.contains("git config --global --add safe.directory C:/Projects/seat-be"), "{msg}");
        assert!(!msg.contains("not a git repo"), "{msg}");
        // A .git that git still refuses: git's own last line, not "not a repo".
        fs::create_dir(dir.path().join(".git")).unwrap();
        let msg = git_open_error(dir.path(), "repo", "git failed: warning: x\nfatal: bad config line 1").unwrap();
        assert_eq!(msg, "Git could not open repo: fatal: bad config line 1");
    }

    #[test]
    fn app_git_never_takes_an_optional_lock() {
        // A background `git status` that writes the index back holds
        // index.lock, and the user's own commit then fails on it.
        let cmd = git_command();
        let set = cmd.get_envs().any(|(k, v)| {
            k == "GIT_OPTIONAL_LOCKS" && v == Some(std::ffi::OsStr::new("0"))
        });
        assert!(set);
    }

    #[test]
    fn a_local_branch_is_found_only_while_it_exists() {
        let dir = tempdir().unwrap();
        git_init_with_commit(dir.path());
        git_run(dir.path(), &["branch", "feature/x"]);
        assert!(local_branch_exists(dir.path(), "feature/x"));
        git_run(dir.path(), &["branch", "-D", "feature/x"]);
        assert!(!local_branch_exists(dir.path(), "feature/x"));
        // A tag or a remote ref by that name is not a local branch.
        git_run(dir.path(), &["tag", "feature/y"]);
        assert!(!local_branch_exists(dir.path(), "feature/y"));
    }

    // ── git history / graph (issue #199) ──

    #[test]
    fn parse_git_log_splits_records_and_refs() {
        let rec = |sha: &str, parents: &str, refs: &str, subject: &str| {
            format!("{sha}\u{1f}{}\u{1f}{parents}\u{1f}Ada\u{1f}ada@example.com\u{1f}1700000000\u{1f}{refs}\u{1f}{subject}\u{1e}", &sha[..7])
        };
        let out = format!(
            "{}\n{}\n{}",
            rec("aaaaaaaaaaaa", "bbbbbbbbbbbb cccccccccccc", "HEAD -> main, origin/main, tag: v1", "merge: land it"),
            rec("bbbbbbbbbbbb", "dddddddddddd", "", "subject, with a comma"),
            rec("dddddddddddd", "", "", "root"),
        );
        let unpushed = ["aaaaaaaaaaaa".to_string()].into_iter().collect();
        let commits = parse_git_log(&out, &unpushed);

        assert_eq!(commits.len(), 3);
        // A merge keeps BOTH parents, in git's order — lane layout depends on
        // first-parent coming first.
        assert_eq!(commits[0].parents, vec!["bbbbbbbbbbbb", "cccccccccccc"]);
        assert_eq!(commits[0].refs, vec!["HEAD -> main", "origin/main", "tag: v1"]);
        assert!(commits[0].unpushed, "rev-list membership must mark the commit outgoing");
        // A comma inside the SUBJECT must not be mistaken for a ref separator.
        assert_eq!(commits[1].subject, "subject, with a comma");
        assert!(commits[1].refs.is_empty());
        assert!(!commits[1].unpushed);
        // A root commit has no parents and that is not a parse failure.
        assert!(commits[2].parents.is_empty());
        assert_eq!(commits[2].timestamp, 1700000000);
    }

    #[test]
    fn parse_git_log_keeps_a_multiline_body_as_one_field() {
        // The body is the last field and holds newlines. That only parses
        // because records are RS-terminated, not newline-terminated: a
        // line-based split would tear every multi-paragraph commit apart.
        let body = "Why it changed.\n\nCo-authored-by: Ada <ada@example.com>";
        let out = format!(
            "abc123456789\u{1f}abc1234\u{1f}\u{1f}Ada\u{1f}ada@example.com\u{1f}1700000000\u{1f}\u{1f}the subject\u{1f}{body}\n\n\u{1e}",
        );
        let commits = parse_git_log(&out, &Default::default());
        assert_eq!(commits.len(), 1);
        assert_eq!(commits[0].subject, "the subject");
        // Trailing blank lines are git's, not the author's.
        assert_eq!(commits[0].body, body);
    }

    #[test]
    fn parse_git_log_leaves_a_one_line_commit_with_an_empty_body() {
        let out = "abc123456789\u{1f}abc1234\u{1f}\u{1f}Ada\u{1f}ada@example.com\u{1f}1700000000\u{1f}\u{1f}subject only\u{1f}\u{1e}";
        let commits = parse_git_log(out, &Default::default());
        assert_eq!(commits.len(), 1);
        assert_eq!(commits[0].subject, "subject only");
        assert!(commits[0].body.is_empty());
    }

    #[test]
    fn parse_git_log_tolerates_empty_and_short_records() {
        assert!(parse_git_log("", &Default::default()).is_empty());
        // Truncated record (fewer fields than the format promises) is skipped
        // rather than panicking on an index.
        assert!(parse_git_log("abc\u{1f}abc\u{1e}", &Default::default()).is_empty());
    }

    #[test]
    fn commit_ish_rejects_anything_but_a_sha() {
        assert!(is_commit_ish("0d86f3a"));
        assert!(is_commit_ish("0d86f3a6ba24515f2492137483333ba979e3450d"));
        assert!(!is_commit_ish(""));
        assert!(!is_commit_ish("HEAD"));
        assert!(!is_commit_ish("--upload-pack=touch /tmp/pwn"));
        assert!(!is_commit_ish("main..HEAD"));
        assert!(!is_commit_ish(&"a".repeat(65)));
    }

    #[test]
    fn safe_rev_accepts_refnames_but_not_option_injection() {
        // The Compare picker hands us real refnames, so unlike is_commit_ish
        // these must pass.
        assert!(is_safe_rev("main"));
        assert!(is_safe_rev("origin/main"));
        assert!(is_safe_rev("feature/gh-208_compare.v2"));
        assert!(is_safe_rev("0d86f3a6ba24515f2492137483333ba979e3450d"));
        // A leading dash is the whole reason this exists.
        assert!(!is_safe_rev("--upload-pack=touch /tmp/pwn"));
        assert!(!is_safe_rev("-c"));
        // Rev SYNTAX is not a refname: the caller peels with ^{commit} itself,
        // and a range would silently change what is being compared.
        assert!(!is_safe_rev("main..HEAD"));
        assert!(!is_safe_rev("HEAD~3"));
        assert!(!is_safe_rev("main^"));
        assert!(!is_safe_rev("refs/heads/*"));
        assert!(!is_safe_rev(""));
        assert!(!is_safe_rev("has space"));
        assert!(!is_safe_rev(&"a".repeat(256)));
    }

    #[test]
    fn name_status_z_keeps_the_destination_of_a_rename() {
        // Exactly what `git diff --name-status -M -z` writes: a plain record is
        // two fields, a rename is three, and the stream ends with a NUL.
        let rows = parse_name_status_z("M\0keep.txt\0R075\0old.txt\0new.txt\0A\0add.txt\0");
        assert_eq!(
            rows,
            vec![
                ("M".to_string(), "keep.txt".to_string()),
                // The similarity score is dropped and the NEW path kept — it is
                // the one `git show <sha>:path` can resolve.
                ("R".to_string(), "new.txt".to_string()),
                ("A".to_string(), "add.txt".to_string()),
            ],
        );
        assert!(parse_name_status_z("").is_empty());
        // A truncated record is dropped, not panicked on.
        assert!(parse_name_status_z("R100\0only-one-path\0").is_empty());
    }

    #[test]
    fn numstat_z_handles_renames_and_binary_files() {
        // A rename leaves the third tab-field EMPTY and follows with two
        // NUL-terminated paths; a binary file reports "-" for both counts.
        let rows = parse_numstat_z("1\t0\tkeep.txt\04\t2\t\0old.txt\0new.txt\0-\t-\tshot.png\0");
        assert_eq!(
            rows,
            vec![
                ("keep.txt".to_string(), Some(1), Some(0)),
                ("new.txt".to_string(), Some(4), Some(2)),
                // Binary churn is unknown, NOT zero.
                ("shot.png".to_string(), None, None),
            ],
        );
        assert!(parse_numstat_z("").is_empty());
    }

    /// A repo on `main` with one committed file, plus a `topic` branch that
    /// commits one file, edits another without committing, and drops an
    /// untracked one. The three ways work can exist in a task, in one fixture.
    fn compare_fixture(repo: &Path) -> String {
        git_init_with_commit(repo);
        git_set_identity(repo);
        git_commit_file(repo, "shared.txt", "one\ntwo\n", "shared on main");
        let main = git_branch(repo);
        git_run(repo, &["checkout", "-q", "-b", "topic"]);
        git_commit_file(repo, "committed.txt", "c\n", "committed on topic");
        fs::write(repo.join("shared.txt"), "one\ntwo\nthree\n").unwrap();
        fs::write(repo.join("untracked.txt"), "u\n").unwrap();
        main
    }

    #[test]
    fn git_compare_merges_committed_staged_and_untracked_work() {
        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        let main = compare_fixture(&repo);

        let cmp = git_compare(&repo, &main, true).unwrap();
        assert_eq!(cmp.branch, "topic");
        assert!(!cmp.no_merge_base);
        let by: std::collections::HashMap<&str, &GitFile> =
            cmp.files.iter().map(|f| (f.path.as_str(), f)).collect();

        // The entire point of the view: a file whose only change is a COMMIT
        // shows up next to one that is merely edited and one git has never seen.
        assert_eq!(by["committed.txt"].status, "A");
        assert_eq!(by["shared.txt"].status, "M");
        assert_eq!(by["untracked.txt"].status, "?");
        assert_eq!(by.len(), 3);

        assert_eq!(by["shared.txt"].added, Some(1));
        assert_eq!(by["shared.txt"].removed, Some(0));
        // Untracked churn can't come from `git diff` (no tree holds the file),
        // so it is counted directly.
        assert_eq!(by["untracked.txt"].added, Some(1));
        // The header total must equal the rows it sits above.
        assert_eq!(cmp.added, cmp.files.iter().filter_map(|f| f.added).sum::<u32>());
        // A worktree-side file carries a real fingerprint, which is what keeps
        // "mark as viewed" working here (unlike a History diff).
        assert!(!by["shared.txt"].fp.is_empty());
    }

    #[test]
    fn git_compare_defaults_to_the_merge_base_so_base_side_work_is_not_inverted() {
        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        let main = compare_fixture(&repo);
        // Someone lands a commit on the base AFTER this task branched.
        git_run(&repo, &["checkout", "-q", &main]);
        git_commit_file(&repo, "later-on-main.txt", "later\n", "landed on main");
        git_run(&repo, &["checkout", "-q", "topic"]);

        let merged = git_compare(&repo, &main, true).unwrap();
        assert!(
            !merged.files.iter().any(|f| f.path == "later-on-main.txt"),
            "three-dot semantics must ignore work the base gained since the branch point",
        );

        // Two-dot is the escape hatch, and there the same file DOES appear —
        // as a deletion, because the topic branch genuinely doesn't have it.
        let direct = git_compare(&repo, &main, false).unwrap();
        let later = direct.files.iter().find(|f| f.path == "later-on-main.txt")
            .expect("tip-to-tree compare sees the base's newer commit");
        assert_eq!(later.status, "D");
        assert_ne!(merged.base_sha, direct.base_sha, "the two modes read different left sides");
    }

    #[test]
    fn blame_parses_incremental_groups_and_dedupes_the_commit_table() {
        // Two commits, three groups: commit A owns lines 1-2 and 5, commit B
        // owns 3-4. A's second group repeats only the sha line, which is the
        // whole reason --incremental is cheap and the reason the parser must
        // not clear already-filled fields.
        let a = "1111111111111111111111111111111111111111";
        let b = "2222222222222222222222222222222222222222";
        let out = format!(
"{a} 1 1 2
author Ada
author-mail <ada@example.com>
author-time 1700000000
author-tz +0000
summary first subject
filename f.rs
{b} 3 3 2
author Grace
author-mail <grace@example.com>
author-time 1700000100
author-tz +0000
summary second subject
filename f.rs
{a} 5 5 1
previous 3333333333333333333333333333333333333333 f.rs
filename f.rs
");
        let (commits, lines) = parse_git_blame_incremental(&out);

        assert_eq!(commits.len(), 2, "a commit owning two groups appears once");
        assert_eq!(commits[0].author, "Ada");
        assert_eq!(commits[0].author_email, "ada@example.com", "angle brackets are stripped");
        assert_eq!(commits[0].author_time, 1700000000);
        assert_eq!(commits[0].summary, "first subject");
        assert!(!commits[0].uncommitted);
        assert_eq!(commits[1].author, "Grace");

        // Line index is 0-based over 1-based git line numbers, and the
        // out-of-order trailing group lands on line 5, not appended.
        assert_eq!(lines, vec![0, 0, 1, 1, 0]);
    }

    #[test]
    fn blame_marks_the_all_zero_sha_as_uncommitted_and_tolerates_gaps() {
        let zero = "0000000000000000000000000000000000000000";
        let out = format!(
"{zero} 1 2 1
author Not Committed Yet
author-mail <not.committed.yet>
author-time 1700000200
author-tz +0000
summary Version of f.rs from f.rs
filename f.rs
");
        // Only line 2 is attributed, so line 1 stays sentinel rather than
        // silently pointing at commit 0, and the index ends where git's
        // numbers end.
        let (commits, lines) = parse_git_blame_incremental(&out);
        assert_eq!(commits.len(), 1);
        assert!(commits[0].uncommitted, "the all-zero sha is a working-tree line");
        assert_eq!(lines, vec![u32::MAX, 0]);
    }

    #[test]
    fn blame_ignores_a_malformed_group_header_and_refuses_an_absurd_count() {
        let a = "1111111111111111111111111111111111111111";
        // First header is malformed (two numbers, not three) and must be
        // skipped without poisoning the following real group.
        let out = format!("{a} 1 1\n{a} 1 1 3\nauthor Ada\nsummary s\nfilename f.rs\n");
        let (commits, lines) = parse_git_blame_incremental(&out);
        assert_eq!(commits.len(), 1, "the malformed header contributed no commit");
        assert_eq!(lines, vec![0, 0, 0]);

        // An absurd line count is refused outright rather than allocating for
        // it. Nothing legitimate gets near BLAME_MAX_LINES.
        let huge = format!("{a} 1 1 {}\nauthor Ada\nsummary s\nfilename f.rs\n", BLAME_MAX_LINES + 1);
        let (_c, l) = parse_git_blame_incremental(&huge);
        assert!(l.is_empty(), "a hostile count must not size the index");
    }

    #[test]
    fn blame_reads_a_real_repo_and_attributes_the_working_tree_edit() {
        let dir = tempdir().unwrap();
        let repo = dir.path();
        git_init_with_commit(repo);
        git_set_identity(repo);
        git_commit_file(repo, "f.txt", "one\ntwo\n", "add f");
        let task = Task { path: repo.to_string_lossy().into_owned(), ..Default::default() };

        let blamed = task_git_blame_for_task(&task, "f.txt").unwrap();
        assert!(!blamed.skipped);
        assert_eq!(blamed.lines.len(), 2);
        assert!(!blamed.head.is_empty(), "head is reported for cache keying");
        let author = &blamed.commits[blamed.lines[0] as usize].author;
        assert!(!author.is_empty(), "a committed line has an author");

        // Blame runs against the WORKING TREE, so an unsaved-then-saved third
        // line is attributed to nobody yet instead of shifting the other two.
        fs::write(repo.join("f.txt"), "one\ntwo\nthree\n").unwrap();
        let dirty = task_git_blame_for_task(&task, "f.txt").unwrap();
        assert_eq!(dirty.lines.len(), 3);
        assert!(
            dirty.commits[dirty.lines[2] as usize].uncommitted,
            "the new line is not committed yet",
        );
        assert!(
            !dirty.commits[dirty.lines[0] as usize].uncommitted,
            "the untouched first line keeps its commit",
        );
    }

    #[test]
    fn commit_offset_locates_a_commit_without_walking_pages() {
        let dir = tempdir().unwrap();
        let repo = dir.path();
        git_init_with_commit(repo);
        git_set_identity(repo);
        let first = git_head(repo);
        for n in 1..=5 {
            git_commit_file(repo, &format!("f{n}.txt"), "x\n", &format!("c{n}"));
        }
        let head = git_head(repo);
        let task = Task { path: repo.to_string_lossy().into_owned(), ..Default::default() };

        // HEAD is at offset 0; the initial commit is 5 commits back. That IS
        // the page `skip` needed to land on it, which is the whole point.
        assert_eq!(task_git_commit_offset_for_task(&task, "", &head).unwrap(), 0);
        assert_eq!(task_git_commit_offset_for_task(&task, "", &first).unwrap(), 5);

        // Non-hex never reaches git as an argument.
        assert!(task_git_commit_offset_for_task(&task, "", "--exec=touch /tmp/pwn").is_err());
        assert!(task_git_commit_offset_for_task(&task, "", "HEAD~2").is_err());
        // Well-formed but absent is an error, not 0 (which would silently scroll
        // the panel to the top and look like a successful reveal).
        assert!(task_git_commit_offset_for_task(&task, "", &"b".repeat(40)).is_err());
    }

    #[test]
    fn commit_meta_reads_one_commit_in_full_and_rejects_a_bad_sha() {
        let dir = tempdir().unwrap();
        let repo = dir.path();
        git_init_with_commit(repo);
        git_set_identity(repo);
        fs::write(repo.join("f.txt"), "one\n").unwrap();
        git_run(repo, &["add", "f.txt"]);
        git_run(repo, &[
            "commit", "-q", "-m",
            "feat: the subject\n\nProse that explains it.\n\nCo-authored-by: Ada <ada@example.com>",
        ]);
        let head = git_head(repo);
        let task = Task { path: repo.to_string_lossy().into_owned(), ..Default::default() };

        let c = task_git_commit_meta_for_task(&task, "f.txt", &head).unwrap();
        assert_eq!(c.sha, head);
        assert_eq!(c.subject, "feat: the subject");
        // The whole message below the subject, trailers included: the popup
        // renders the prose and pulls co-authors out on the frontend.
        assert!(c.body.contains("Prose that explains it."));
        assert!(c.body.contains("Co-authored-by: Ada <ada@example.com>"));
        assert!(!c.author.is_empty() && !c.email.is_empty());
        assert!(c.timestamp > 0);

        // Anything that is not hex never reaches git as an argument.
        assert!(task_git_commit_meta_for_task(&task, "f.txt", "--exec=touch /tmp/pwn").is_err());
        assert!(task_git_commit_meta_for_task(&task, "f.txt", "HEAD~1").is_err());
        // Well-formed but absent is an error, not an empty commit.
        assert!(task_git_commit_meta_for_task(&task, "f.txt", &"a".repeat(40)).is_err());
    }

    #[test]
    fn blame_is_silent_for_an_untracked_file_and_outside_a_repo() {
        let dir = tempdir().unwrap();
        let repo = dir.path();
        git_init_with_commit(repo);
        fs::write(repo.join("untracked.txt"), "hi\n").unwrap();
        let task = Task { path: repo.to_string_lossy().into_owned(), ..Default::default() };

        // Untracked: empty, NOT an error. The editor shows nothing rather than
        // a git failure on every file it opens.
        let untracked = task_git_blame_for_task(&task, "untracked.txt").unwrap();
        assert!(untracked.commits.is_empty() && untracked.lines.is_empty());
        assert!(!untracked.skipped, "empty is not the same signal as skipped");

        let plain = tempdir().unwrap();
        fs::write(plain.path().join("f.txt"), "hi\n").unwrap();
        let non_git = Task { path: plain.path().to_string_lossy().into_owned(), ..Default::default() };
        let out = task_git_blame_for_task(&non_git, "f.txt").unwrap();
        assert!(out.commits.is_empty() && out.head.is_empty());
    }

    #[test]
    fn git_compare_rejects_a_ref_that_is_not_in_the_repo() {
        let dir = tempdir().unwrap();
        git_init_with_commit(dir.path());
        assert!(git_compare(dir.path(), "no-such-branch", true).is_err());
        // And never lets a dash reach git as an option.
        assert!(git_compare(dir.path(), "--exec=touch /tmp/pwn", true).is_err());
    }

    #[test]
    fn compare_diff_sides_read_the_base_against_the_working_tree() {
        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        let main = compare_fixture(&repo);
        let cmp = git_compare(&repo, &main, true).unwrap();
        let scope = format!("base:{}", cmp.base_sha);
        let task = task_at(&repo);

        // Committed on the branch: absent from the base, present on the right.
        let added = task_file_diff_sides_for_task(&task, "committed.txt", Some(&scope)).unwrap();
        assert!(!added.original_exists && added.modified_exists);
        assert_eq!(added.modified, "c\n");

        // Edited but never committed: the base still has the ORIGINAL, which is
        // what an unstaged- or staged-scoped diff could not have shown.
        let edited = task_file_diff_sides_for_task(&task, "shared.txt", Some(&scope)).unwrap();
        assert_eq!(edited.original, "one\ntwo\n");
        assert_eq!(edited.modified, "one\ntwo\nthree\n");
        // The right side is the live file, so the review affordances stay on.
        assert!(!edited.fp.is_empty());

        // A garbage sha in the scope must not silently fall through to the
        // default HEAD-vs-worktree sides.
        let bogus = task_file_diff_sides_for_task(&task, "shared.txt", Some("base:not-hex")).unwrap();
        assert_eq!(bogus.original, "one\ntwo\n", "an unparseable scope falls back to HEAD");
    }

    #[test]
    fn git_log_page_reads_real_history_with_a_merge() {
        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        git_init_with_commit(&repo);
        git_set_identity(&repo);
        git_commit_file(&repo, "a.txt", "a\n", "on main");
        let main = git_branch(&repo);
        git_run(&repo, &["checkout", "-q", "-b", "topic"]);
        git_commit_file(&repo, "t.txt", "t\n", "on topic");
        git_run(&repo, &["checkout", "-q", &main]);
        git_run(&repo, &["merge", "--no-ff", "-m", "merge topic", "topic"]);

        let page = git_log_page(&repo, 0, 50, false, false, "", &[]);
        assert_eq!(page.branch, main);
        assert!(page.upstream.is_empty(), "a local-only repo has no upstream");
        let subjects: Vec<&str> = page.commits.iter().map(|c| c.subject.as_str()).collect();
        assert!(subjects.contains(&"merge topic"));
        assert!(subjects.contains(&"on topic"), "--topo-order must include the merged-in branch");
        let merge = page.commits.iter().find(|c| c.subject == "merge topic").unwrap();
        assert_eq!(merge.parents.len(), 2, "merge must expose both parents to the lane layout");
        assert!(merge.refs.iter().any(|r| r.contains("HEAD")), "the tip carries the HEAD decoration");
        // Without an upstream nothing is claimed to be outgoing.
        assert!(page.commits.iter().all(|c| !c.unpushed));
    }


    #[test]
    fn grep_searches_the_whole_history_not_the_first_page() {
        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        git_init_with_commit(&repo);
        git_set_identity(&repo);
        git_commit_file(&repo, "needle.txt", "x\n", "Fix the LOGIN bug");
        for i in 0..12 {
            git_commit_file(&repo, &format!("f{i}.txt"), "y\n", &format!("filler {i}"));
        }
        // A page this small would not reach the match by paging.
        let page = git_log_page(&repo, 0, 3, false, false, "login", &[]);
        let subjects: Vec<String> = page.commits.iter().map(|c| c.subject.clone()).collect();
        assert_eq!(subjects, vec!["Fix the LOGIN bug".to_string()], "case-insensitive, from anywhere in the history");
        assert!(!page.has_more);
    }

    #[test]
    fn grep_is_a_literal_string_not_a_regex() {
        // The filter box is a filter box: a bracket in it is a character
        // someone typed, and a half-typed regex must not become an error.
        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        git_init_with_commit(&repo);
        git_set_identity(&repo);
        git_commit_file(&repo, "a.txt", "a\n", "fix(git): a [bracketed] subject");
        git_commit_file(&repo, "b.txt", "b\n", "unrelated");

        let hit = git_log_page(&repo, 0, 50, false, false, "[bracketed]", &[]);
        assert_eq!(hit.commits.len(), 1);
        // An unbalanced bracket is a query with no matches, never a crash.
        let none = git_log_page(&repo, 0, 50, false, false, "[unclosed", &[]);
        assert!(none.commits.is_empty());
    }

    #[test]
    fn grep_matches_the_body_too_and_stacks_with_a_scope() {
        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        git_init_with_commit(&repo);
        git_set_identity(&repo);
        std::fs::write(repo.join("c.txt"), "c\n").unwrap();
        git_run(&repo, &["add", "-A"]);
        git_run(&repo, &["commit", "-q", "-m", "terse subject", "-m", "the reason lives in the BODY"]);

        assert_eq!(git_log_page(&repo, 0, 50, false, false, "body", &[]).commits.len(), 1);
        // Search narrows a scope, it does not replace it: an empty ref list is
        // still HEAD, and --all is still every ref.
        assert_eq!(git_log_page(&repo, 0, 50, true, false, "body", &[]).commits.len(), 1);
        assert!(git_log_page(&repo, 0, 50, false, false, "nothing matches this", &[]).commits.is_empty());
    }

    #[test]
    fn first_parent_collapses_a_merged_branch_into_its_merge() {
        // The complaint this answers: picking "main" still drew a lane per
        // merged branch, because every commit on those branches IS an ancestor
        // of main. First-parent walks only the mainline, so the merge is one
        // row and the side commit is not walked at all.
        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        git_init_with_commit(&repo);
        git_set_identity(&repo);
        let main = git_branch(&repo);
        git_run(&repo, &["checkout", "-q", "-b", "topic"]);
        git_commit_file(&repo, "t.txt", "t\n", "only on topic");
        git_run(&repo, &["checkout", "-q", &main]);
        git_run(&repo, &["merge", "--no-ff", "-m", "merge topic", "topic"]);

        let full = git_log_page(&repo, 0, 50, false, false, "", &[]);
        let subjects = |p: &GitLogPage| p.commits.iter().map(|c| c.subject.clone()).collect::<Vec<_>>();
        assert!(subjects(&full).contains(&"only on topic".to_string()));

        let fp = git_log_page(&repo, 0, 50, false, true, "", &[]);
        assert!(subjects(&fp).contains(&"merge topic".to_string()), "the merge itself must stay");
        assert!(
            !subjects(&fp).contains(&"only on topic".to_string()),
            "the merged side branch must collapse into its merge",
        );
        assert!(fp.commits.len() < full.commits.len());
    }

    #[test]
    fn first_parent_is_ignored_under_all_refs() {
        // --all exists to show every tip; pruning the topology under it would
        // draw tips with no path to them.
        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        git_init_with_commit(&repo);
        git_set_identity(&repo);
        let main = git_branch(&repo);
        git_run(&repo, &["checkout", "-q", "-b", "topic"]);
        git_commit_file(&repo, "t.txt", "t\n", "only on topic");
        git_run(&repo, &["checkout", "-q", &main]);

        let all = git_log_page(&repo, 0, 50, true, true, "", &[]);
        assert!(all.commits.iter().any(|c| c.subject == "only on topic"));
    }

    #[test]
    fn git_log_page_paginates_and_reports_more() {
        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        git_init_with_commit(&repo);
        git_set_identity(&repo);
        for i in 0..5 {
            git_commit_file(&repo, &format!("f{i}.txt"), "x\n", &format!("commit {i}"));
        }
        let first = git_log_page(&repo, 0, 2, false, false, "", &[]);
        assert_eq!(first.commits.len(), 2, "a page must not leak the lookahead row");
        assert!(first.has_more);
        let second = git_log_page(&repo, 2, 2, false, false, "", &[]);
        assert_eq!(second.commits.len(), 2);
        assert_ne!(first.commits[0].sha, second.commits[0].sha, "skip must advance the page");
        // The tail page knows it is the tail.
        let tail = git_log_page(&repo, 0, 500, false, false, "", &[]);
        assert!(!tail.has_more);
    }

    /// A repo with an unmerged side branch, which is the only shape where the
    /// three scopes (HEAD / picked refs / --all) give three different answers.
    fn repo_with_side_branch(repo: &Path) -> (String, String) {
        git_init_with_commit(repo);
        git_set_identity(repo);
        git_commit_file(repo, "a.txt", "a\n", "on main");
        let main = git_branch(repo);
        git_run(repo, &["checkout", "-q", "-b", "side"]);
        git_commit_file(repo, "s.txt", "s\n", "only on side");
        git_run(repo, &["checkout", "-q", &main]);
        (main, "side".to_string())
    }

    #[test]
    fn ahead_count_is_zero_without_an_upstream_and_counts_unpushed_after_one() {
        let origin_dir = tempdir().unwrap();
        let origin = origin_dir.path().to_path_buf();
        git_run(&origin, &["init", "-q", "--bare", "-b", "main"]);

        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        git_init_with_commit(&repo);
        git_set_identity(&repo);
        let branch = git_branch(&repo);

        // No upstream: "everything is unpushed" is not a number worth badging.
        assert_eq!(ahead_count(&repo), 0);

        git_run(&repo, &["remote", "add", "origin", origin.to_str().unwrap()]);
        git_run(&repo, &["push", "-q", "-u", "origin", &branch]);
        assert_eq!(ahead_count(&repo), 0, "in sync with the upstream");

        git_commit_file(&repo, "a.txt", "a\n", "one");
        git_commit_file(&repo, "b.txt", "b\n", "two");
        assert_eq!(ahead_count(&repo), 2, "two commits the remote does not have");

        // The badge clears once they are sent, via the same helper the button
        // calls, so the button and the count cannot disagree.
        git_push(&repo).unwrap();
        assert_eq!(ahead_count(&repo), 0);
    }

    #[test]
    fn git_push_sets_the_upstream_when_the_branch_has_none() {
        let origin_dir = tempdir().unwrap();
        let origin = origin_dir.path().to_path_buf();
        git_run(&origin, &["init", "-q", "--bare", "-b", "main"]);

        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        git_init_with_commit(&repo);
        git_set_identity(&repo);
        git_run(&repo, &["remote", "add", "origin", origin.to_str().unwrap()]);

        // The fresh-worktree case: a plain `git push` fails here, and the
        // fallback has to create the upstream rather than surface the error.
        git_push(&repo).unwrap();
        assert!(
            git(&["rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{upstream}"], &repo).is_ok(),
            "push must leave the branch tracking its remote",
        );
        assert_eq!(ahead_count(&repo), 0);
    }

    #[test]
    fn git_refs_lists_branches_and_tags_without_remote_head() {
        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        let (main, side) = repo_with_side_branch(&repo);
        git_run(&repo, &["tag", "v1"]);

        let refs = git_refs(&repo);
        let names: Vec<&str> = refs.iter().map(|r| r.name.as_str()).collect();
        assert!(names.contains(&main.as_str()));
        assert!(names.contains(&side.as_str()));
        assert!(names.contains(&"v1"));
        // Kinds drive the picker's grouping, so they have to be right.
        assert_eq!(refs.iter().find(|r| r.name == side).unwrap().kind, "branch");
        assert_eq!(refs.iter().find(|r| r.name == "v1").unwrap().kind, "tag");
        // Every entry carries a sha to show beside the name.
        assert!(refs.iter().all(|r| !r.sha.is_empty()));
        // `origin/HEAD` is an alias for another row; offering it would let the
        // same history be picked twice under two names.
        assert!(!names.iter().any(|n| n.ends_with("/HEAD")));
    }

    #[test]
    fn allowed_refs_is_an_allowlist_that_dedupes_and_keeps_order() {
        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        let (main, side) = repo_with_side_branch(&repo);

        let asked = vec![side.clone(), main.clone(), side.clone()];
        assert_eq!(allowed_refs(&repo, &asked), vec![side.clone(), main.clone()]);

        // The whole point: nothing that is not a real ref survives, so a
        // caller-supplied string can never reach argv as a flag or a path.
        let hostile = vec![
            "--all".to_string(),
            "--upload-pack=touch /tmp/pwned".to_string(),
            "-n1".to_string(),
            "no-such-branch".to_string(),
            "../etc/passwd".to_string(),
        ];
        assert!(allowed_refs(&repo, &hostile).is_empty());
    }

    #[test]
    fn git_log_page_scopes_to_head_picked_refs_or_all() {
        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        let (main, side) = repo_with_side_branch(&repo);
        let subjects = |p: &GitLogPage| -> Vec<String> {
            p.commits.iter().map(|c| c.subject.clone()).collect()
        };

        // Default: HEAD only. The unmerged side commit is not this branch's.
        let head = git_log_page(&repo, 0, 50, false, false, "", &[]);
        assert!(subjects(&head).contains(&"on main".to_string()));
        assert!(!subjects(&head).contains(&"only on side".to_string()));

        // --all wins over everything and brings the sibling in.
        let all = git_log_page(&repo, 0, 50, true, false, "", &[]);
        assert!(subjects(&all).contains(&"only on side".to_string()));

        // Picked: just the side branch, which does NOT contain main's tip.
        let picked = git_log_page(&repo, 0, 50, false, false, "", &[side.clone()]);
        assert!(subjects(&picked).contains(&"only on side".to_string()));

        // Picked both = the union, which is what --all shows in this repo.
        let both = git_log_page(&repo, 0, 50, false, false, "", &[main.clone(), side.clone()]);
        assert_eq!(both.commits.len(), all.commits.len());

        // all_branches beats a refs list rather than intersecting with it.
        let all_wins = git_log_page(&repo, 0, 50, true, false, "", &[side.clone()]);
        assert_eq!(all_wins.commits.len(), all.commits.len());
    }

    #[test]
    fn git_log_page_returns_nothing_when_every_picked_ref_is_gone() {
        let dir = tempdir().unwrap();
        let repo = dir.path().to_path_buf();
        let (main, _side) = repo_with_side_branch(&repo);
        // A branch deleted while the picker still lists it. Falling back to
        // HEAD would answer a different question under the old scope's label.
        let page = git_log_page(&repo, 0, 50, false, false, "", &["deleted-branch".to_string()]);
        assert!(page.commits.is_empty());
        assert!(!page.has_more);
        // The header still knows where it is, so the panel keeps its chrome.
        assert_eq!(page.branch, main);
    }

